window.AUTH=window.AUTH||{};window.AUTH["18-1116"]={"d":"18-1116","id":"2019/18-1116","n":"Intel Corp. Investment Policy Committee v. Sulyma","briefs":[{"k":"petitioner","label":"Brief of petitioners Intel Corporation Investment Policy Committee, et al.","date":"2019-08-21","url":"https://www.supremecourt.gov/DocketPDF/18/18-1116/113110/20190821150536247_18-1116%20ts.pdf","side":"pet","n":66},{"k":"respondent","label":"Brief of respondent Christopher M. Sulyma","date":"2019-10-21","url":"https://www.supremecourt.gov/DocketPDF/18/18-1116/119693/20191021162852735_Respondent%20Brief%2010.21%20Final.pdf","side":"res","n":64},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2019-10-28","url":"https://www.supremecourt.gov/DocketPDF/18/18-1116/120552/20191028185235180_18-1116bsacUnitedStates.pdf","side":"us","n":95},{"k":"reply","label":"Reply of petitioners Intel Corporation Investment Policy Committee, et al.","date":"2019-11-20","url":"https://www.supremecourt.gov/DocketPDF/18/18-1116/123079/20191120123350788_18-1116%20rb.pdf","side":"pet","n":51}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/589US2PP_final.pdf#page=70","tr":true,"items":[{"t":"case","label":"FEDERAL CASES Americare Sys., Inc. v. Pinckney","cite":"635 F. App’x 305","y":2016,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/635/305/","by":{"0":"27"}},{"t":"case","label":"Bartlett v. Dep’t of the Treasury","cite":"749 F.3d 1","y":2014,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/749/1/","by":{"0":"27"}},{"t":"case","label":"Brock v. Nellis","cite":"809 F.2d 753","y":1987,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/809/753/","op":1,"by":{"0":"34","1":"18, 36","2":"13, 30"}},{"t":"case","label":"Brown v. Am. Life Holdings, Inc.","cite":"190 F.3d 856","y":1999,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/190/856/","sum":"Finding claim time- barred where plaintiff contended that investments were improperly undiversified and admitted he knew the nature of the investments when made; undiversified nature of investments would have been evident from plan disclosures.","sumSrc":"brief:0","by":{"0":"36"}},{"t":"case","label":"Brown v. Owens Corning Investment Review Committee","cite":"622 F.3d 564","y":2010,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/622/564/","op":1,"sum":"Holding that when plaintiffs were provided with summary plan descriptions containing the relevant facts, “[a]ctual knowledge does not require proof that the individual Plaintiffs actually saw or read” them.","sumSrc":"brief:0","by":{"0":"21","1":"11, 41","2":"14"}},{"t":"case","label":"Cetel v. Kirwan Fin. Grp.","cite":"460 F.3d 494","y":2006,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/460/494/","sum":"Holding that plaintiffs have “actual knowledge of the alleged breach” when the “evidence establishes that [they] were in possession of the material facts necessary to understand that some claim exists”.","sumSrc":"brief:0","by":{"0":"27","3":"11"}},{"t":"case","label":"CIGNA Corp. v. Amara","cite":"563 U.S. 421","y":2011,"id":"2010/09-804","sc":1,"sum":"The Court held that the U.S. District Court for the District of Connecticut did not have the authority to reform CIGNA's pension plan.","sumSrc":"Oyez","by":{"0":"6","2":"25"}},{"t":"case","label":"Conkright v. Frommert","cite":"559 U.S. 506","y":2010,"id":"2009/08-810","sc":1,"op":2,"sum":"The Court held that the Second Circuit Court of Appeals erred when they did not hold a claim of unfair pension distribution by employees of the Xerox Corporation to a deferential standard of review.","sumSrc":"Oyez","by":{"0":"2, 4, 41, 47"}},{"t":"case","label":"Curtiss-Wright Corp. v. Schoonejongen","cite":"514 U.S. 73","y":1995,"id":"1994/93-1935","sc":1,"sum":"Petitioner Curtiss-Wright Corp. amended its employee benefit plan to provide that the postretirement health care coverage it had maintained for many years would cease for retirees upon the termination of business operations in the facility from which they retired. In ruling for respondent retirees in their ensuing suit, the District Court found, among other things, that the new provision constituted an \"amendment\" …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"6"}},{"t":"case","label":"Donovan v. Bierwirth","cite":"754 F.2d 1049","y":1985,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/754/1049/","by":{"0":"44"}},{"t":"case","label":"Edes v. Verizon Commc’ns, Inc.","cite":"417 F.3d 133","y":2005,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/417/133/","by":{"0":"32, 33","1":"21, 23"}},{"t":"case","label":"Enneking v. Schmidt Builders Supply Inc.","cite":"875 F. Supp. 2d 1274","y":2012,"court":"D. Kan.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/875/1274/","by":{"0":"33"}},{"t":"case","label":"Erhard v. Commissioner","cite":"87 F.3d 273","y":1996,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/87/273/","by":{"0":"33","3":"13"}},{"t":"case","label":"Firestone Tire & Rubber Co. v. Bruch","cite":"489 U.S. 101","y":1989,"id":"1988/87-1054","sc":1,"op":1,"sum":"Petitioner Firestone Tire & Rubber Co. (Firestone) maintained, and was the plan administrator and fiduciary of, a termination pay plan and two other unfunded employee benefit plans governed by the Employee Retirement Income Security Act of 1974 (ERISA), 29 U. S. C. § 1001 et seq. After Firestone sold its Plastics Division to Occidental Petroleum Co. (Occidental), respondents, Plastics Division employees who were …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4, 17, 24"}},{"t":"case","label":"Fish v. GreatBanc Tr. Co.","cite":"749 F.3d 671","y":2014,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/749/671/","ar":1,"sum":"Holding that “actual knowledge of the procedures used or not used by the fiduciar[ies]” is often needed for imprudent-investment claims.","sumSrc":"brief:1","by":{"0":"36","1":"18, 19, 23, 27","2":"26"}},{"t":"case","label":"Flores-Figueroa v. United States","cite":"556 U.S. 646","y":2009,"id":"2008/08-108","sc":1,"sum":"The Court found that in order to prove aggravated identity theft, the government needs to prove that the defendant knew that the identification he possessed belonged to another person.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Gerosa v. Savasta & Co.","cite":"329 F.3d 317","y":2003,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/329/317/","by":{"0":"41"}},{"t":"case","label":"Global-Tech Appliances, Inc. v. SEB S.A.","cite":"563 U.S. 754","y":2011,"id":"2010/10-6","sc":1,"op":1,"ar":3,"sum":"The Court ruled that induced infringement under the patent clause requires knowledge that the induced acts constitute patent infringement.","sumSrc":"Oyez","by":{"0":"23, 33, 35","1":"26, 27, 28","2":"21, 22","3":"8"}},{"t":"case","label":"Gobeille v. Liberty Mutual Ins. Co.","cite":"136 S. Ct. 936","y":2016,"id":"2015/14-181","sc":1,"op":1,"sum":"The Court determined that the reporting requirements of the Employee Retirement Income Security Act of 1974 (ERISA) preempt a Vermont state statute regarding reporting requirements as applied to a self-insured employee health plan.","sumSrc":"Oyez","by":{"0":"41, 47","2":"27","3":"21"}},{"t":"case","label":"Home Depot U. S. A., Inc. v. Jackson","cite":"139 S. Ct. 1743","y":2019,"id":"2018/17-1471","sc":1,"sum":"Neither the general removal provision, 28 U. S. C. §1441(a), nor the removal provision in the Class Action Fairness Act of 2005, §1453(b), permit a third-party counterclaim defendant to remove a class-action claim from state to federal court.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"24"}},{"t":"case","label":"Int’l Union of Electronic, Electric, Salaried, Mach. & Furniture Workers v. Murata Erie N. Am., Inc.","cite":"980 F.2d 889","y":1992,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/980/889/","sum":"Rejecting limitations defense where plan documents disclosed fact that plan had been amended but not the specific contents of the amendment that allegedly constituted a breach of fiduciary duty.","sumSrc":"brief:0","by":{"0":"37","2":"26"}},{"t":"case","label":"LaRue v. DeWolff, Boberg & Assocs.","cite":"552 U.S. 248","y":2008,"id":"2007/06-856","sc":1,"ar":1,"by":{"0":"4"}},{"t":"case","label":"Lockheed Corp. v. Spink","cite":"517 U.S. 882","y":1996,"id":"1995/95-809","sc":1,"sum":"In unanimous and 7-2 decisions, announced by Justice Clarence Thomas, the Court ruled that businesses may condition early retirement benefits on the forfeiture of the right to sue in a job-related claim. The Court also ruled that the government could not retroactively apply retirement income benefit laws.","sumSrc":"Oyez","by":{"0":"4","1":"4"}},{"t":"case","label":"Lorenz v. Safeway, Inc.","cite":"241 F. Supp. 3d 1005","y":2017,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/241/1005/","by":{"0":"33"}},{"t":"case","label":"Mertens v. Hewitt Assocs.","cite":"508 U.S. 248","y":1993,"id":"1992/91-1671","sc":1,"sum":"ERISA does not authorize suits for money damages against nonfiduciaries who knowingly participate in a fiduciary's breach of fiduciary duty. ERISA §502(a)(3) permits plan participants to bring civil actions to obtain \"appropriate equitable relief\" to redress violations of the statute or a plan. Assuming, arguendo,that this creates a cause of action against nonfiduciaries who knowingly assist in a fiduciary's breach …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4, 47"}},{"t":"case","label":"Estate of Pepper v. Whitehead","cite":"686 F.3d 658","y":2012,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/686/658/","by":{"0":"34"}},{"t":"case","label":"Reeves v. Airlite Plastics Co.","cite":"2005 WL 2347242","y":2005,"court":"D. Neb. Sept. 26","by":{"0":"30, 32, 33, 44","3":"15"}},{"t":"case","label":"Rush Prudential HMO, Inc. v. Moran","cite":"536 U.S. 355","y":2002,"id":"2001/00-1021","sc":1,"sum":"The Court held that ERISA does not preempt the Illinois HMO Act.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Shirk v. Fifth Third Bancorp","cite":"2009 WL 3150303","y":2009,"court":"S.D. Ohio Sept. 30","by":{"0":"33"}},{"t":"case","label":"Star Athletica, LLC v. Varsity Brands, Inc.","cite":"137 S. Ct. 1002","y":2017,"id":"2016/15-866","sc":1,"sum":"The Court determined that the test for deciding whether a feature of a “useful article” is copyrightable under the Copyright Act is whether the feature can be perceived as a two- or three-dimensional artwork that is separable from the useful article and if it would be a protectable pictorial, graphical, or sculptural work on its own.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"UMG Recordings, Inc. v. Shelter Capital Partners LLC","cite":"718 F.3d 1006","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/718/1006/","by":{"0":"22"}},{"t":"case","label":"United States v. Wells","cite":"163 F.3d 889","y":1998,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/163/889/","by":{"0":"23","2":"22"}},{"t":"case","label":"United States v. Zayyad","cite":"741 F.3d 452","y":2014,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/741/452/","by":{"0":"23","1":"27","2":"22"}},{"t":"case","label":"Varity Corp. v. Howe","cite":"516 U.S. 489","y":1996,"id":"1995/94-1471","sc":1,"sum":"The Court held that, under the specific factual circumstances, Varity and Massey-Ferguson acted in their capacity as an ERISA fiduciary when they significantly and deliberately misled the plan's beneficiaries, thereby violating their fiduciary obligations imposed by ERISA.","sumSrc":"Oyez","by":{"0":"41","2":"25"}},{"t":"case","label":"Walters v. Metro. Educ. Enters., Inc.","cite":"519 U.S. 202","y":1997,"id":"1996/95-259","sc":1,"sum":"Authored by Justice Antonin Scalia, the Court ruled that the ultimate touchstone under Title VII of the Civil Rights Act of 1964 is whether an employer has employment relationships with 15 or more individuals for each working day in 20 or more weeks during the year in question.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Waste Mgmt. Holdings, Inc. v. Mowbray","cite":"208 F.3d 288","y":2000,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/208/288/","by":{"0":"46"}},{"t":"case","label":"Yates v. United States","cite":"135 S. Ct. 1074","y":2015,"id":"2014/13-7451","sc":1,"ar":2,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"0":"22","3":"4"}},{"t":"case","label":"Young v. General Motors Investment Mgmt. Corp.","cite":"550 F. Supp. 2d 416","y":2008,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/550/416/","sum":"Observing that construing “actual knowledge” subjectively would allow a participant to avoid the statute of limitations by “disregard[ing] information clearly provided” to her.","sumSrc":"brief:0","by":{"0":"29, 33, 36, 44"}},{"t":"case","label":"STATE CASES Brown v. N. Am. Mfg. Co.","cite":"576 P.2d 711","y":1978,"court":"Mont.","url":"https://www.courtlistener.com/c/P.2d/576/711/","by":{"0":"31"}},{"t":"case","label":"Kugel v. Knuckles","cite":"69 S.W. 595","y":1902,"court":"Mo. Ct. App.","url":"https://www.courtlistener.com/c/S.W./69/595/","by":{"0":"23","1":"29, 30","3":"10"}},{"t":"case","label":"People v. Barker","cite":"96 P.3d 507","y":2004,"court":"Cal.","url":"https://www.courtlistener.com/c/P.3d/96/507/","by":{"0":"23","1":"31"}},{"t":"case","label":"Poffenberger v. Risser","cite":"431 A.2d 677","y":1981,"court":"Md.","url":"https://www.courtlistener.com/c/A.2d/431/677/","by":{"0":"23","1":"30","3":"10"}},{"t":"usc","label":"26 U.S.C. § 401","url":"https://www.law.cornell.edu/uscode/text/26/401","subs":["(k)(12)(D)"],"by":{"0":"7, 26"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"29 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/29/1001","subs":["(b)"],"stext":{"head":"§1001. Congressional findings and declaration of policy","paras":[[0,"(a) Benefit plans as affecting interstate commerce and the Federal taxing power"],[0,"The Congress finds that the growth in size, scope, and numbers of employee benefit plans in recent years has been rapid and substantial; that the operational scope and economic impact of such plans is increasingly interstate; that the continued well-being and security of millions of employees and their dependents are directly affected by these plans; that they are affected with a national public interest; that they have become an important factor affecting the stability of employment and the successful development of industrial relations; that they have become an important factor in commerce because of the interstate character of their activities, and of the activities of their participants, and the employers, employee organizations, and other entities by which they are established or maintained; that a large volume of the activities of such plans are carried on by means of the mails and instrumentalities of interstate commerce; that owing to the lack of employee information and adequate safeguards concerning their operation, it is desirable in the interests of employees and their beneficiaries, and to provide for the general welfare and the free flow of commerce, that disclosure be made and safeguards be provided with respect to the establishment, operation, and administration of such plans; that they substantially affect the revenues of the United States because they are afforded preferential Federal tax treatment; that despite the enormous growth in such plans many employees with long years of employment are losing anticipated retirement benefits owing to the lack of vesting provisions in such plans; that owing to the inadequacy of current minimum standards, the soundness and stability of plans with respect to adequate funds to pay promised benefits may be endangered; that owing to the termination of plans before requisite funds have been accumulated, employees and their beneficiaries have been deprived of anticipated benefits; and that it is therefore desirable in the interests of employees and their beneficiaries, for the protection of the revenue of the United States, and to provide for the free flow of commerce, that minimum standards be provided assuring the equitable character of such plans and their financial soundness."],[0,"(b) Protection of interstate commerce and beneficiaries by requiring disclosure and reporting, setting standards of conduct, etc., for fiduciaries"],[0,"It is hereby declared to be the policy of this chapter to protect interstate commerce and the interests of participants in employee benefit plans and their beneficiaries, by requiring the disclosure and reporting to participants and beneficiaries of financial and other information with respect thereto, by establishing standards of conduct, responsibility, and obligation for fiduciaries of employee benefit plans, and by providing for appropriate remedies, sanctions, and ready access to the Federal courts."],[0,"(c) Protection of interstate commerce, the Federal taxing power, and beneficiaries by vesting of accrued benefits, setting minimum standards of funding, requiring termination insurance"],[0,"It is hereby further declared to be the policy of this chapter to protect interstate commerce, the Federal taxing power, and the interests of participants in private pension plans and their beneficiaries by improving the equitable character and the soundness of such plans by requiring them to vest the accrued benefits of employees with significant periods of service, to meet minimum standards of funding, and by requiring plan termination insurance."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1001?type=usc&year=mostrecent&link-type=html"},"head":"§1001. Congressional findings and declaration of policy","tname":"Labor","by":{"0":"25, 27","2":"1, 2","3":"4"}},{"t":"usc","label":"29 U.S.C. § 1021","url":"https://www.law.cornell.edu/uscode/text/29/1021","subs":["(a)(1)","(b)","(i)(2)(A)"],"stext":{"head":"§1021. Duty of disclosure and reporting","paras":[[0,"(a) Summary plan description and information to be furnished to participants and beneficiaries"],[0,"The administrator of each employee benefit plan shall cause to be furnished in accordance with section 1024(b) of this title to each participant covered under the plan and to each beneficiary who is receiving benefits under the plan—"],[1,"(1) a summary plan description described in section 1022(a)(1) 1 of this title; and"],[1,"(2) the information described in subsection (f) and sections 1024(b)(3) and 1025(a) and (c) of this title."],[0,"(b) Reports to be filed with Secretary of Labor"],[0,"The administrator shall, in accordance with section 1024(a) of this title, file with the Secretary—"],[1,"(1) the annual report containing the information required by section 1023 of this title; and"],[1,"(2) terminal and supplementary reports as required by subsection (c) of this section."],[0,"(c) Terminal and supplementary reports"],[0,"(1) Each administrator of an employee pension benefit plan which is winding up its affairs (without regard to the number of participants remaining in the plan) shall, in accordance with regulations prescribed by the Secretary, file such terminal reports as the Secretary may consider necessary. A copy of such report shall also be filed with the Pension Benefit Guaranty Corporation."],[0,"(2) The Secretary may require terminal reports to be filed with regard to any employee welfare benefit plan which is winding up its affairs in accordance with regulations promulgated by the Secretary."],[0,"(3) The Secretary may require that a plan described in paragraph (1) or (2) file a supplementary or terminal report with the annual report in the year such plan is terminated and that a copy of such supplementary or terminal report in the case of a plan described in paragraph (1) be also filed with the Pension Benefit Guaranty Corporation."],[0,"(d) Notice of failure to meet minimum funding standards"],[0,"(1) In general"],[1,"If an employer maintaining a plan other than a multiemployer plan fails to make a required installment or other payment required to meet the minimum funding standard under section 1082 of this title to a plan before the 60th day following the due date for such installment or other payment, the employer shall notify each participant and beneficiary (including an alternate payee as defined in section 1056(d)(3)(K) of this title) of such plan of such failure. Such notice shall be made at such time and in such manner as the Secretary may prescribe."],[0,"(2) Subsection not to apply if waiver pending"],[1,"This subsection shall not apply to any failure if the employer has filed a waiver request under section 1083 or 1085a of this title with respect to the plan year to which the required installment relates, except that if the waiver request is denied, notice under paragraph (1) shall be provided within 60 days after the date of such denial."],[0,"(3) Definitions"],[1,"For purposes of this subsection, the terms \"required installment\" and \"due date\" have the same meanings given such terms by section 1083(j) or 1085a(f) of this title, whichever is applicable."],[0,"(e) Notice of transfer of excess pension assets to health benefits accounts"],[0,"(1) Notice to participants"],[1,"Not later than 60 days before the date of a qualified transfer by an employee pension benefit plan of excess pension assets to a health benefits account or applicable life insurance account, the administrator of the plan shall notify (in such manner as the Secretary may prescribe) each participant and beneficiary under the plan of such transfer. Such notice shall include information with respect to the amount of excess pension assets, the portion to be transferred, the amount of health benefits liabilities or applicable life insurance benefit liabilities expected to be provided with the assets transferred, and the amount of pension benefits of the participant which will be nonforfeitable immediately after the transfer."],[0,"(2) Notice to Secretaries, administrator, and employee organizations"],[0,"(A) In general"],[2,"Not later than 60 days before the date of any qualified transfer by an employee pension benefit plan of excess pension assets to a health benefits account or applicable life insurance account, the employer maintaining the plan from which the transfer is made shall provide the Secretary, the Secretary of the Treasury, the administrator, and each employee organization representing participants in the plan a written notice of such transfer. A copy of any such notice shall be available for inspection in the principal office of the administrator."],[0,"(B) Information relating to transfer"],[2,"Such notice shall identify the plan from which the transfer is made, the amount of the transfer, a detailed accounting of assets projected to be held by the plan immediately before and immediately after the transfer, and the current liabilities under the plan at the time of the transfer."],[0,"(C) Authority for additional reporting requirements"],[2,"The Secretary may prescribe such additional reporting requirements as may be necessary to carry out the purposes of this section."],[0,"(3) Definitions"],[1,"For purposes of paragraph (1), any term used in such paragraph which is also used in section 420 of title 26 (as in effect on December 29, 2022) shall have the same meaning as when used in such section."],[0,"(f) Defined benefit plan funding notices"],[0,"(1) In general"],[1,"The administrator of a defined benefit plan to which subchapter III applies shall for each plan year provide a plan funding notice to the Pension Benefit Guaranty Corporation, to each plan participant and beneficiary, to each labor organization representing such participants or beneficiaries, and, in the case of a multiemployer plan, to each employer that has an obligation to contribute to the plan."],[0,"(2) Information contained in notices"],[0,"(A) Identifying information"],[2,"Each notice required under paragraph (1) shall contain identifying information, including the name of the plan, the address and phone number of the plan administrator and the plan's principal administrative officer, each plan sponsor's employer identification number, and the plan number of the plan."],[0,"(B) Specific information"],[2,"A plan funding notice under paragraph (1) shall include—"],[3,"(i)(I) in the case of a single-employer plan, a statement as to whether the plan's percentage of plan liabilities funded (as described in clause (ii)(I)(bb)) for the plan year to which the notice relates, and for the 2 preceding plan years, is at least 100 percent (and, if not, the actual percentages), or"],[3,"(II) in the case of a multiemployer plan, a statement as to whether the plan's funded percentage (as defined in section 1085(i) 1 of this title) for the plan year to which the notice relates, and for the 2 preceding plan years, is at least 100 percent (and, if not, the actual percentages),"],[3,"(ii)(I) in the case of a single-employer plan—"],[4,"(aa) a statement of the value of the plan's assets and liabilities for the plan year to which the notice relates as of the last day of the plan year to which the notice relates, and for the preceding 2 plan years as of the last day of each such plan year, determined using the asset valuation under subclause (II) of section 1306(a)(3)(E)(iii) of this title and the interest rate under section 1306(a)(3)(E)(iv) of this title,"],[4,"(bb) for purposes of the statement in subparagraph (B)(i)(I), the percentage of plan liabilities funded, calculated as the ratio between the value of the plan's assets and liabilities, as determined under item (aa), for the plan year to which the notice relates and for the 2 preceding plan years, and"],[4,"(cc) if the information in (aa) and (bb) is presented in tabular form, a statement that describes that in the event of a plan termination the corporation's calculation of plan liabilities may be greater and that references the section of the notice with the information required under clause (x), and"],[3,"(II) in the case of a multiemployer plan, a statement, for the plan year to which the notice relates and the preceding 2 plan years, of the value of the plan assets (determined both in the same manner as under section 1084 of this title and under the rules of subclause (I)(aa)) and the value of the plan liabilities (determined in the same manner as under section 1084 of this title except that the method specified in section 1085(i)(8) 1 of this title shall be used),"],[3,"(iii) a statement of the number of participants for the plan year to which the notice relates as of the last day of such plan year and the preceding 2 plan years, in tabular format, who are—"],[4,"(I) retired or separated from service and are receiving benefits,"],[4,"(II) retired or separated participants entitled to future benefits, and"],[4,"(III) active participants under the plan,"],[3,"(iv) a statement setting forth the funding policy of the plan, the asset allocation of investments under the plan (expressed as percentages of total assets), and the average return on assets for the plan year, as of the end of the plan year to which the notice relates,"],[3,"(v) in the case of a multiemployer plan, whether the plan was in critical or endangered status under section 1085 of this title for such plan year and, if so—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1021?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1021. Duty of disclosure and reporting","tname":"Labor","by":{"0":"25, 27","2":"23, 24, 23, 24, 27, 25, 25","3":"4, 22"}},{"t":"usc","label":"29 U.S.C. § 1022","url":"https://www.law.cornell.edu/uscode/text/29/1022","subs":["(a)","(b)"],"stext":{"head":"§1022. Summary plan description","paras":[[0,"(a) A summary plan description of any employee benefit plan shall be furnished to participants and beneficiaries as provided in section 1024(b) of this title. The summary plan description shall include the information described in subsection (b), shall be written in a manner calculated to be understood by the average plan participant, and shall be sufficiently accurate and comprehensive to reasonably apprise such participants and beneficiaries of their rights and obligations under the plan. A summary of any material modification in the terms of the plan and any change in the information required under subsection (b) shall be written in a manner calculated to be understood by the average plan participant and shall be furnished in accordance with section 1024(b)(1) of this title."],[0,"(b) The summary plan description shall contain the following information: The name and type of administration of the plan; in the case of a group health plan (as defined in section 1191b(a)(1) of this title), whether a health insurance issuer (as defined in section 1191b(b)(2) of this title) is responsible for the financing or administration (including payment of claims) of the plan and (if so) the name and address of such issuer; the name and address of the person designated as agent for the service of legal process, if such person is not the administrator; the name and address of the administrator; names, titles, and addresses of any trustee or trustees (if they are persons different from the administrator); a description of the relevant provisions of any applicable collective bargaining agreement; the plan's requirements respecting eligibility for participation and benefits; a description of the provisions providing for nonforfeitable pension benefits; circumstances which may result in disqualification, ineligibility, or denial or loss of benefits; the source of financing of the plan and the identity of any organization through which benefits are provided; the date of the end of the plan year and whether the records of the plan are kept on a calendar, policy, or fiscal year basis; the procedures to be followed in presenting claims for benefits under the plan including the office at the Department of Labor through which participants and beneficiaries may seek assistance or information regarding their rights under this chapter and the Health Insurance Portability and Accountability Act of 1996 with respect to health benefits that are offered through a group health plan (as defined in section 1191b(a)(1) of this title), the remedies available under the plan for the redress of claims which are denied in whole or in part (including procedures required under section 1133 of this title), and if the employer so elects for purposes of complying with section 1181(f)(3)(B)(i) of this title, the model notice applicable to the State in which the participants and beneficiaries reside."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1022?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1022. Summary plan description","tname":"Labor","by":{"0":"6, 26, 6","2":"23","3":"4, 5, 21"}},{"t":"usc","label":"29 U.S.C. § 1024","url":"https://www.law.cornell.edu/uscode/text/29/1024","subs":["(b)(1)(A)","(a)(2)(B)","(b)(1)"],"stext":{"head":"§1024. Filing with Secretary and furnishing information to participants and certain employers","paras":[[0,"(a) Filing of annual report with Secretary"],[0,"(1) The administrator of any employee benefit plan subject to this part shall file with the Secretary the annual report for a plan year within 210 days after the close of such year (or within such time as may be required by regulations promulgated by the Secretary in order to reduce duplicative filing). The Secretary shall make copies of such annual reports available for inspection in the public document room of the Department of Labor."],[0,"(2)(A) With respect to annual reports required to be filed with the Secretary under this part, the Secretary may by regulation prescribe simplified annual reports for any pension plan that—"],[1,"(i) covers fewer than 100 participants; or"],[1,"(ii) is a plan described in section 1060(a) of this title that covers fewer than 1,000 participants, but only if no single employer in the plan has 100 or more participants covered by the plan."],[0,"(B) Nothing contained in this paragraph shall preclude the Secretary from requiring any information or data from any such plan to which this part applies where he finds such data or information is necessary to carry out the purposes of this subchapter nor shall the Secretary be precluded from revoking provisions for simplified reports for any such plan if he finds it necessary to do so in order to carry out the objectives of this subchapter."],[0,"(3) The Secretary may by regulation exempt any welfare benefit plan from all or part of the reporting and disclosure requirements of this subchapter, or may provide for simplified reporting and disclosure if he finds that such requirements are inappropriate as applied to welfare benefit plans."],[0,"(4) The Secretary may reject any filing under this section—"],[1,"(A) if he determines that such filing is incomplete for purposes of this part; or"],[1,"(B) if he determines that there is any material qualification by an accountant or actuary contained in an opinion submitted pursuant to section 1023(a)(3)(A) or section 1023(a)(4)(B) of this title."],[0,"(5) If the Secretary rejects a filing of a report under paragraph (4) and if a revised filing satisfactory to the Secretary is not submitted within 45 days after the Secretary makes his determination under paragraph (4) to reject the filing, and if the Secretary deems it in the best interest of the participants, he may take any one or more of the following actions—"],[1,"(A) retain an independent qualified public accountant (as defined in section 1023(a)(3)(D) of this title) on behalf of the participants to perform an audit,"],[1,"(B) retain an enrolled actuary (as defined in section 1023(a)(4)(C) of this title) on behalf of the plan participants, to prepare an actuarial statement,"],[1,"(C) bring a civil action for such legal or equitable relief as may be appropriate to enforce the provisions of this part, or"],[1,"(D) take any other action authorized by this subchapter."],[0,"The administrator shall permit such accountant or actuary to inspect whatever books and records of the plan are necessary for such audit. The plan shall be liable to the Secretary for the expenses for such audit or report, and the Secretary may bring an action against the plan in any court of competent jurisdiction to recover such expenses."],[0,"(6) The administrator of any employee benefit plan subject to this part shall furnish to the Secretary, upon request, any documents relating to the employee benefit plan, including but not limited to, the latest summary plan description (including any summaries of plan changes not contained in the summary plan description), and the bargaining agreement, trust agreement, contract, or other instrument under which the plan is established or operated."],[0,"(b) Publication of summary plan description and annual report to participants and beneficiaries of plan"],[0,"Publication of the summary plan descriptions and annual reports shall be made to participants and beneficiaries of the particular plan as follows:"],[0,"(1) The administrator shall furnish to each participant, and each beneficiary receiving benefits under the plan, a copy of the summary plan description, and all modifications and changes referred to in section 1022(a) of this title—"],[1,"(A) within 90 days after he becomes a participant, or (in the case of a beneficiary) within 90 days after he first receives benefits, or"],[1,"(B) if later, within 120 days after the plan becomes subject to this part."],[0,"The administrator shall furnish to each participant, and each beneficiary receiving benefits under the plan, every fifth year after the plan becomes subject to this part an updated summary plan description described in section 1022 of this title which integrates all plan amendments made within such five-year period, except that in a case where no amendments have been made to a plan during such five-year period this sentence shall not apply. Notwithstanding the foregoing, the administrator shall furnish to each participant, and to each beneficiary receiving benefits under the plan, the summary plan description described in section 1022 of this title every tenth year after the plan becomes subject to this part. If there is a modification or change described in section 1022(a) of this title (other than a material reduction in covered services or benefits provided in the case of a group health plan (as defined in section 1191b(a)(1) of this title)), a summary description of such modification or change shall be furnished not later than 210 days after the end of the plan year in which the change is adopted to each participant, and to each beneficiary who is receiving benefits under the plan. If there is a modification or change described in section 1022(a) of this title that is a material reduction in covered services or benefits provided under a group health plan (as defined in section 1191b(a)(1) of this title), a summary description of such modification or change shall be furnished to participants and beneficiaries not later than 60 days after the date of the adoption of the modification or change. In the alternative, the plan sponsors may provide such description at regular intervals of not more than 90 days. The Secretary shall issue regulations within 180 days after August 21, 1996, providing alternative mechanisms to delivery by mail through which group health plans (as so defined) may notify participants and beneficiaries of material reductions in covered services or benefits."],[0,"(2) The administrator shall make copies of the latest updated summary plan description and the latest annual report and the bargaining agreement, trust agreement, contract, or other instruments under which the plan was established or is operated available for examination by any plan participant or beneficiary in the principal office of the administrator and in such other places as may be necessary to make available all pertinent information to all participants (including such places as the Secretary may prescribe by regulations)."],[0,"(3) Within 210 days after the close of the fiscal year of the plan, the administrator (other than an administrator of a defined benefit plan to which the requirements of section 1021(f) of this title applies) 1 shall furnish to each participant, and to each beneficiary receiving benefits under the plan, a copy of the statements and schedules, for such fiscal year, described in subparagraphs (A) and (B) of section 1023(b)(3) of this title and such other material (including the percentage determined under section 1023(d)(11) of this title) as is necessary to fairly summarize the latest annual report."],[0,"(4) The administrator shall, upon written request of any participant or beneficiary, furnish a copy of the latest updated summary,2 plan description, and the latest annual report, any terminal report, the bargaining agreement, trust agreement, contract, or other instruments under which the plan is established or operated. The administrator may make a reasonable charge to cover the cost of furnishing such complete copies. The Secretary may by regulation prescribe the maximum amount which will constitute a reasonable charge under the preceding sentence."],[0,"(5) Identification and basic plan information and actuarial information included in the annual report for any plan year shall be filed with the Secretary in an electronic format which accommodates display on the Internet, in accordance with regulations which shall be prescribed by the Secretary. The Secretary shall provide for display of such information included in the annual report, within 90 days after the date of the filing of the annual report, on an Internet website maintained by the Secretary and other appropriate media. Such information shall also be displayed on any Intranet website maintained by the plan sponsor (or by the plan administrator on behalf of the plan sponsor) for the purpose of communicating with employees and not the public, in accordance with regulations which shall be prescribed by the Secretary."],[0,"(c) Statement of rights"],[0,"The Secretary may by regulation require that the administrator of any employee benefit plan furnish to each participant and to each beneficiary receiving benefits under the plan a statement of the rights of participants and beneficiaries under this subchapter."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1024?type=usc&year=mostrecent&link-type=html"},"head":"§1024. Filing with Secretary and furnishing information to participants and certain employers","tname":"Labor","by":{"0":"6","2":"27, 27, 24, 3"}},{"t":"usc","label":"29 U.S.C. § 1104","url":"https://www.law.cornell.edu/uscode/text/29/1104","subs":["(a)","(c)(5)(B)(ii)","(a)(1)"],"stext":{"head":"§1104. Fiduciary duties","paras":[[0,"(a) Prudent man standard of care"],[0,"(1) Subject to sections 1103(c) and (d), 1342, and 1344 of this title, a fiduciary shall discharge his duties with respect to a plan solely in the interest of the participants and beneficiaries and—"],[1,"(A) for the exclusive purpose of:"],[2,"(i) providing benefits to participants and their beneficiaries; and"],[2,"(ii) defraying reasonable expenses of administering the plan;"],[1,"(B) with the care, skill, prudence, and diligence under the circumstances then prevailing that a prudent man acting in a like capacity and familiar with such matters would use in the conduct of an enterprise of a like character and with like aims;"],[1,"(C) by diversifying the investments of the plan so as to minimize the risk of large losses, unless under the circumstances it is clearly prudent not to do so; and"],[1,"(D) in accordance with the documents and instruments governing the plan insofar as such documents and instruments are consistent with the provisions of this subchapter and subchapter III."],[0,"(2) In the case of an eligible individual account plan (as defined in section 1107(d)(3) of this title), the diversification requirement of paragraph (1)(C) and the prudence requirement (only to the extent that it requires diversification) of paragraph (1)(B) is not violated by acquisition or holding of qualifying employer real property or qualifying employer securities (as defined in section 1107(d)(4) and (5) of this title)."],[0,"(b) Indicia of ownership of assets outside jurisdiction of district courts"],[0,"Except as authorized by the Secretary by regulations, no fiduciary may maintain the indicia of ownership of any assets of a plan outside the jurisdiction of the district courts of the United States."],[0,"(c) Control over assets by participant or beneficiary"],[0,"(1)(A) In the case of a pension plan which provides for individual accounts and permits a participant or beneficiary to exercise control over the assets in his account, if a participant or beneficiary exercises control over the assets in his account (as determined under regulations of the Secretary)—"],[1,"(i) such participant or beneficiary shall not be deemed to be a fiduciary by reason of such exercise, and"],[1,"(ii) no person who is otherwise a fiduciary shall be liable under this part for any loss, or by reason of any breach, which results from such participant's or beneficiary's exercise of control, except that this clause shall not apply in connection with such participant or beneficiary for any blackout period during which the ability of such participant or beneficiary to direct the investment of the assets in his or her account is suspended by a plan sponsor or fiduciary."],[0,"(B) If a person referred to in subparagraph (A)(ii) meets the requirements of this subchapter in connection with authorizing and implementing the blackout period, any person who is otherwise a fiduciary shall not be liable under this subchapter for any loss occurring during such period."],[0,"(C) For purposes of this paragraph, the term \"blackout period\" has the meaning given such term by section 1021(i)(7) of this title."],[0,"(2) In the case of a simple retirement account established pursuant to a qualified salary reduction arrangement under section 408(p) of title 26, a participant or beneficiary shall, for purposes of paragraph (1), be treated as exercising control over the assets in the account upon the earliest of—"],[1,"(A) an affirmative election among investment options with respect to the initial investment of any contribution,"],[1,"(B) a rollover to any other simple retirement account or individual retirement plan, or"],[1,"(C) one year after the simple retirement account is established."],[0,"No reports, other than those required under section 1021(g) of this title, shall be required with respect to a simple retirement account established pursuant to such a qualified salary reduction arrangement."],[0,"(3) In the case of a pension plan which makes a transfer to an individual retirement account or annuity of a designated trustee or issuer under section 401(a)(31)(B) of title 26, the participant or beneficiary shall, for purposes of paragraph (1), be treated as exercising control over the assets in the account or annuity upon—"],[1,"(A) the earlier of—"],[2,"(i) a rollover of all or a portion of the amount to another individual retirement account or annuity; or"],[2,"(ii) one year after the transfer is made; or"],[1,"(B) a transfer that is made in a manner consistent with guidance provided by the Secretary."],[0,"(4)(A) In any case in which a qualified change in investment options occurs in connection with an individual account plan, a participant or beneficiary shall not be treated for purposes of paragraph (1) as not exercising control over the assets in his account in connection with such change if the requirements of subparagraph (C) are met in connection with such change."],[0,"(B) For purposes of subparagraph (A), the term \"qualified change in investment options\" means, in connection with an individual account plan, a change in the investment options offered to the participant or beneficiary under the terms of the plan, under which—"],[1,"(i) the account of the participant or beneficiary is reallocated among one or more remaining or new investment options which are offered in lieu of one or more investment options offered immediately prior to the effective date of the change, and"],[1,"(ii) the stated characteristics of the remaining or new investment options provided under clause (i), including characteristics relating to risk and rate of return, are, as of immediately after the change, reasonably similar to those of the existing investment options as of immediately before the change."],[0,"(C) The requirements of this subparagraph are met in connection with a qualified change in investment options if—"],[1,"(i) at least 30 days and no more than 60 days prior to the effective date of the change, the plan administrator furnishes written notice of the change to the participants and beneficiaries, including information comparing the existing and new investment options and an explanation that, in the absence of affirmative investment instructions from the participant or beneficiary to the contrary, the account of the participant or beneficiary will be invested in the manner described in subparagraph (B),"],[1,"(ii) the participant or beneficiary has not provided to the plan administrator, in advance of the effective date of the change, affirmative investment instructions contrary to the change, and"],[1,"(iii) the investments under the plan of the participant or beneficiary as in effect immediately prior to the effective date of the change were the product of the exercise by such participant or beneficiary of control over the assets of the account within the meaning of paragraph (1)."],[0,"(5) Default investment arrangements.—"],[1,"(A) In general.—For purposes of paragraph (1), a participant or beneficiary in an individual account plan meeting the notice requirements of subparagraph (B) shall be treated as exercising control over the assets in the account with respect to the amount of contributions and earnings which, in the absence of an investment election by the participant or beneficiary, are invested by the plan in accordance with regulations prescribed by the Secretary. The regulations under this subparagraph shall provide guidance on the appropriateness of designating default investments that include a mix of asset classes consistent with capital preservation or long-term capital appreciation, or a blend of both."],[1,"(B) Notice requirements.—"],[2,"(i) In general.—The requirements of this subparagraph are met if each participant or beneficiary—"],[3,"(I) receives, within a reasonable period of time before each plan year, a notice explaining the employee's right under the plan to designate how contributions and earnings will be invested and explaining how, in the absence of any investment election by the participant or beneficiary, such contributions and earnings will be invested, and"],[3,"(II) has a reasonable period of time after receipt of such notice and before the beginning of the plan year to make such designation."],[2,"(ii) Form of notice.—The requirements of clauses (i) and (ii) of section 401(k)(12)(D) of title 26 shall apply with respect to the notices described in this subparagraph."],[0,"(6) Default investment arrangements for a pension-linked emergency savings account.—For purposes of paragraph (1), a participant in a pension-linked emergency savings account shall be treated as exercising control over the assets in the account with respect to the amount of contributions and earnings which are invested in accordance with section 1193(c)(1)(A)(iii) of this title."],[0,"(d) Plan terminations"],[0,"(1) If, in connection with the termination of a pension plan which is a single-employer plan, there is an election to establish or maintain a qualified replacement plan, or to increase benefits, as provided under section 4980(d) of title 26, a fiduciary shall discharge the fiduciary's duties under this subchapter and subchapter III in accordance with the following requirements:"],[1,"(A) In the case of a fiduciary of the terminated plan, any requirement—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1104?type=usc&year=mostrecent&link-type=html"},"head":"§1104. Fiduciary duties","tname":"Labor","by":{"0":"13, 6, 26","1":"4","2":"6, 2, 4","3":"22"}},{"t":"usc","label":"29 U.S.C. § 1113","url":"https://www.law.cornell.edu/uscode/text/29/1113","subs":["(1)","(2)","(a)(2)(1976)"],"stext":{"head":"§1113. Limitation of actions","paras":[[0,"No action may be commenced under this subchapter with respect to a fiduciary's breach of any responsibility, duty, or obligation under this part, or with respect to a violation of this part, after the earlier of—"],[1,"(1) six years after (A) the date of the last action which constituted a part of the breach or violation, or (B) in the case of an omission the latest date on which the fiduciary could have cured the breach or violation, or"],[1,"(2) three years after the earliest date on which the plaintiff had actual knowledge of the breach or violation;"],[0,"except that in the case of fraud or concealment, such action may be commenced not later than six years after the date of discovery of such breach or violation."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1113?type=usc&year=mostrecent&link-type=html"},"op":3,"ar":2,"head":"§1113. Limitation of actions","tname":"Labor","by":{"0":"passim, 5, 28, passim, 39","1":"passim","2":"passim, 2, 5, 10, 11, 15, 29, passim","3":"passim, passim, 1, 6, 16"}},{"t":"usc","label":"29 U.S.C. § 1132","url":"https://www.law.cornell.edu/uscode/text/29/1132","subs":["(a)(2)","(a)(3)","(a)(5)","(c)","(h)"],"stext":{"head":"§1132. Civil enforcement","paras":[[0,"(a) Persons empowered to bring a civil action"],[0,"A civil action may be brought—"],[1,"(1) by a participant or beneficiary—"],[2,"(A) for the relief provided for in subsection (c) of this section, or"],[2,"(B) to recover benefits due to him under the terms of his plan, to enforce his rights under the terms of the plan, or to clarify his rights to future benefits under the terms of the plan;"],[1,"(2) by the Secretary, or by a participant, beneficiary or fiduciary for appropriate relief under section 1109 of this title;"],[1,"(3) by a participant, beneficiary, or fiduciary (A) to enjoin any act or practice which violates any provision of this subchapter or the terms of the plan, or (B) to obtain other appropriate equitable relief (i) to redress such violations or (ii) to enforce any provisions of this subchapter or the terms of the plan;"],[1,"(4) by the Secretary, or by a participant, or beneficiary for appropriate relief in the case of a violation of section 1025(c) or 1032(a) of this title;"],[1,"(5) except as otherwise provided in subsection (b), by the Secretary (A) to enjoin any act or practice which violates any provision of this subchapter, or (B) to obtain other appropriate equitable relief (i) to redress such violation or (ii) to enforce any provision of this subchapter;"],[1,"(6) by the Secretary to collect any civil penalty under paragraph (2), (4), (5), (6), (7), (8), or (9) of subsection (c) or under subsection (i) or (l);"],[1,"(7) by a State to enforce compliance with a qualified medical child support order (as defined in section 1169(a)(2)(A) of this title);"],[1,"(8) by the Secretary, or by an employer or other person referred to in section 1021(f)(1) of this title, (A) to enjoin any act or practice which violates subsection (f) of section 1021 of this title, or (B) to obtain appropriate equitable relief (i) to redress such violation or (ii) to enforce such subsection;"],[1,"(9) in the event that the purchase of an insurance contract or insurance annuity in connection with termination of an individual's status as a participant covered under a pension plan with respect to all or any portion of the participant's pension benefit under such plan constitutes a violation of part 4 of this title 1 or the terms of the plan, by the Secretary, by any individual who was a participant or beneficiary at the time of the alleged violation, or by a fiduciary, to obtain appropriate relief, including the posting of security if necessary, to assure receipt by the participant or beneficiary of the amounts provided or to be provided by such insurance contract or annuity, plus reasonable prejudgment interest on such amounts;"],[1,"(10) in the case of a multiemployer plan that has been certified by the actuary to be in endangered or critical status under section 1085 of this title, if the plan sponsor—"],[2,"(A) has not adopted a funding improvement or rehabilitation plan under that section by the deadline established in such section, or"],[2,"(B) fails to update or comply with the terms of the funding improvement or rehabilitation plan in accordance with the requirements of such section,"],[1,"by an employer that has an obligation to contribute with respect to the multiemployer plan or an employee organization that represents active participants in the multiemployer plan, for an order compelling the plan sponsor to adopt a funding improvement or rehabilitation plan or to update or comply with the terms of the funding improvement or rehabilitation plan in accordance with the requirements of such section and the funding improvement or rehabilitation plan; or"],[1,"(11) in the case of a multiemployer plan, by an employee representative, or any employer that has an obligation to contribute to the plan, (A) to enjoin any act or practice which violates subsection (k) of section 1021 of this title (or, in the case of an employer, subsection (l) of such section), or (B) to obtain appropriate equitable relief (i) to redress such violation or (ii) to enforce such subsection."],[0,"(b) Plans qualified under Internal Revenue Code; maintenance of actions involving delinquent contributions"],[0,"(1) In the case of a plan which is qualified under section 401(a), 403(a), or 405(a) 2 of title 26 (or with respect to which an application to so qualify has been filed and has not been finally determined) the Secretary may exercise his authority under subsection (a)(5) with respect to a violation of, or the enforcement of, parts 2 and 3 of this subtitle (relating to participation, vesting, and funding), only if—"],[1,"(A) requested by the Secretary of the Treasury, or"],[1,"(B) one or more participants, beneficiaries, or fiduciaries, of such plan request in writing (in such manner as the Secretary shall prescribe by regulation) that he exercise such authority on their behalf. In the case of such a request under this paragraph he may exercise such authority only if he determines that such violation affects, or such enforcement is necessary to protect, claims of participants or beneficiaries to benefits under the plan."],[0,"(2) The Secretary shall not initiate an action to enforce section 1145 of this title."],[0,"(3) Except as provided in subsections (c)(9) and (a)(6) (with respect to collecting civil penalties under subsection (c)(9)), the Secretary is not authorized to enforce under this part any requirement of part 7 against a health insurance issuer offering health insurance coverage in connection with a group health plan (as defined in section 1191b(a)(1) of this title). Nothing in this paragraph shall affect the authority of the Secretary to issue regulations to carry out such part."],[0,"(c) Administrator's refusal to supply requested information; penalty for failure to provide annual report in complete form"],[0,"(1) Any administrator (A) who fails to meet the requirements of paragraph (1) or (4) of section 1166 2 of this title, section 1021(e)(1) of this title, section 1021(f) of this title,,3 section 1025(a) of this title, or section 1032(a) of this title with respect to a participant or beneficiary, or (B) who fails or refuses to comply with a request for any information which such administrator is required by this subchapter to furnish to a participant or beneficiary (unless such failure or refusal results from matters reasonably beyond the control of the administrator) by mailing the material requested to the last known address of the requesting participant or beneficiary within 30 days after such request may in the court's discretion be personally liable to such participant or beneficiary in the amount of up to $100 a day from the date of such failure or refusal, and the court may in its discretion order such other relief as it deems proper. For purposes of this paragraph, each violation described in subparagraph (A) with respect to any single participant, and each violation described in subparagraph (B) with respect to any single participant or beneficiary, shall be treated as a separate violation."],[0,"(2) The Secretary may assess a civil penalty against any plan administrator of up to $1,000 a day from the date of such plan administrator's failure or refusal to file the annual report required to be filed with the Secretary under section 1021(b)(1) of this title. For purposes of this paragraph, an annual report that has been rejected under section 1024(a)(4) of this title for failure to provide material information shall not be treated as having been filed with the Secretary."],[0,"(3) Any employer maintaining a plan who fails to meet the notice requirement of section 1021(d) of this title with respect to any participant or beneficiary or who fails to meet the requirements of section 1021(e)(2) of this title with respect to any person or who fails to meet the requirements of section 1082(d)(12)(E) 2 of this title with respect to any person may in the court's discretion be liable to such participant or beneficiary or to such person in the amount of up to $100 a day from the date of such failure, and the court may in its discretion order such other relief as it deems proper."],[0,"(4) The Secretary may assess a civil penalty of not more than $1,000 a day for each violation by any person of subsection (j), (k), or (l) of section 1021 of this title or section 1144(e)(3) of this title."],[0,"(5) The Secretary may assess a civil penalty against any person of up to $1,000 a day from the date of the person's failure or refusal to file the information required to be filed by such person with the Secretary under regulations prescribed pursuant to section 1021(g) of this title."],[0,"(6) If, within 30 days of a request by the Secretary to a plan administrator for documents under section 1024(a)(6) of this title, the plan administrator fails to furnish the material requested to the Secretary, the Secretary may assess a civil penalty against the plan administrator of up to $100 a day from the date of such failure (but in no event in excess of $1,000 per request). No penalty shall be imposed under this paragraph for any failure resulting from matters reasonably beyond the control of the plan administrator."],[0,"(7) The Secretary may assess a civil penalty against a plan administrator of up to $100 a day from the date of the plan administrator's failure or refusal to provide notice to participants and beneficiaries in accordance with subsection (i) or (m) of section 1021 of this title. For purposes of this paragraph, each violation with respect to any single participant or beneficiary shall be treated as a separate violation."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1132?type=usc&year=mostrecent&link-type=html"},"head":"§1132. Civil enforcement","tname":"Labor","by":{"0":"4, 25, 25","2":"1, 2, 29, 2, 29, 2, 24, 28"}},{"t":"law","label":"Pub. L. No. 100-203","url":"https://www.govinfo.gov/link/statute/101/1330","by":{"0":"39","1":"5","2":"16"}},{"t":"reg","label":"29 C.F.R. § 2520.102-2","url":"https://www.ecfr.gov/current/title-29/section-2520.102-2","subs":["(a)"],"by":{"0":"7","3":"21"}},{"t":"reg","label":"29 C.F.R. § 2520.104b-1","url":"https://www.ecfr.gov/current/title-29/section-2520.104b-1","subs":["(b)","(c)","(c)(1)(i)","(c)(1)(iii)"],"by":{"0":"26, 8, 27","1":"35","3":"12, 12"}},{"t":"reg","label":"29 C.F.R. § 2550.404a-5","url":"https://www.ecfr.gov/current/title-29/section-2550.404a-5","subs":["(e)(5)"],"by":{"0":"7, 43, 26","3":"19"}},{"t":"reg","label":"29 C.F.R. § 2550.404c-5","url":"https://www.ecfr.gov/current/title-29/section-2550.404c-5","subs":["(c)(3)","(d)"],"by":{"0":"6, 26, 6, 26"}},{"t":"reg","label":"75 Fed. Reg. 64,910","url":"https://www.govinfo.gov/link/fr/75/64910","by":{"0":"7"}},{"t":"case","label":"Advocate Health Care Network v. Stapleton","cite":"137 S. Ct. 1652","y":2017,"id":"2016/16-74","sc":1,"sum":"The Court determined that the “church plan” exemption of the Employee Retirement Income Security Act of 1974 (ERISA) applies to plans that are maintained by a qualifying church-affiliated organization, even if that organization did not originally establish the plan.","sumSrc":"Oyez","by":{"1":"32, 34"}},{"t":"case","label":"Ali v. Federal Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"sum":"The Court agreed with the 11th Circuit and, in a 5-4 majority opinion written by Justice Clarence Thomas, held that the use of the word \"any\" should be given its normal interpretation, encompassing all federal officers whether or not they were involved in enforcing customs or excise laws.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Bay Area Laundry & Dry Cleaning Pension Trust Fund v. Ferbar Corp. of California, Inc.","cite":"522 U.S. 192","y":1997,"id":"1997/96-370","sc":1,"sum":"The Court held that the MPPAA's six-year statute of limitations on a pension fund's action to collect unpaid withdrawal liability does not begin to run until the employer fails to make a payment on the schedule set by the fund.","sumSrc":"Oyez","by":{"1":"20, 37, 39"}},{"t":"case","label":"Blanton v. Anzalone","cite":"760 F.2d 989","y":1985,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/760/989/","by":{"1":"41"}},{"t":"case","label":"California Public Employees’ Retirement System v. ANZ Securities, Inc.","cite":"137 S. Ct. 2042","y":2017,"id":"2016/16-373","sc":1,"sum":"The Court determined that the filing of a putative class action lawsuit does not satisfy the three-year time limit in Section 13 of the Securities Act with respect to the individual claims of other class members.","sumSrc":"Oyez","by":{"1":"20, 36","2":"29"}},{"t":"case","label":"Caputo v. Pfizer, Inc.","cite":"267 F.3d 181","y":2001,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/267/181/","op":1,"sum":"Explaining that these other provisions show that “when the Legislature intends to incorporate a constructive knowledge requirement into an ERISA statute of limitations, it ordinarily does so explicitly”.","sumSrc":"brief:1","by":{"1":"20, 21, 23","2":"13, 30"}},{"t":"case","label":"Central States, Southeast & Southwest Areas Pension Fund v. Mississippi Warehouse Corp.","cite":"853 F. Supp. 1053","y":1994,"court":"N.D. Ill.","url":"https://www.courtlistener.com/c/F.%20Supp./853/1053/","sum":"Holding that section 1451’s three-year period, which starts when the plaintiff “acquired or should have acquired actual knowledge,” was triggered by documents “made available” to the plaintiff, who “should have known” their contents, even though “actual knowledge is unclear”.","sumSrc":"brief:1","by":{"1":"33"}},{"t":"case","label":"Colby v. Riggs National Bank","cite":"92 F.2d 183","y":1937,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/92/183/","by":{"1":"16, 17"}},{"t":"case","label":"Corley v. United States","cite":"556 U.S. 303","y":2009,"id":"2008/07-10441","sc":1,"sum":"The Court found that voluntary confessions made more than six hours after arrest before the person has been presented before judicial officers are inadmissible.","sumSrc":"Oyez","by":{"1":"33, 34"}},{"t":"case","label":"Farmer v. Brennan","cite":"511 U.S. 825","y":1994,"id":"1993/92-7247","sc":1,"op":1,"sum":"The Supreme Court held that prison officials may be liable if they showed “deliberate indifference” to a substantial risk of serious harm when the official was subjectively aware of the risk and disregarded it. The Court remanded the case for further consideration of whether prison officials were aware of the risk to Farmer.","sumSrc":"Oyez","by":{"1":"30","2":"31"}},{"t":"case","label":"Federal Housing Finance Agency for Federal National Mortgage Ass’n v. Nomura Holding America, Inc.","cite":"873 F.3d 85","y":2017,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/873/85/","by":{"1":"30"}},{"t":"case","label":"Fink v. National Savings & Trust Co.","cite":"772 F.2d 951","y":1985,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/772/951/","ar":1,"sum":"Observing that “[t]he statute provides that constructive knowledge is obtained through reports filed with the Secretary of Labor”.","sumSrc":"brief:2","by":{"1":"23","2":"15, 16","3":"22"}},{"t":"case","label":"Gluck v. Unisys Corp.","cite":"960 F.2d 1168","y":1992,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/960/1168/","op":1,"by":{"1":"18, 19, 20, 23","2":"13, 20"}},{"t":"case","label":"Hardt v. Reliance Standard Life Insurance Co.","cite":"560 U.S. 242","y":2010,"id":"2009/09-448","sc":1,"op":1,"sum":"The Court held that a party is entitled to attorneys' fees pursuant to Section 502(g)(1) of the Employee Retirement Income Security Act when an ERISA violation has occurred.","sumSrc":"Oyez","by":{"1":"16","2":"11"}},{"t":"case","label":"Henderson v. United States","cite":"135 S. Ct. 1780","y":2015,"id":"2014/13-1487","sc":1,"sum":"The Court held that a felony conviction does not prevent a court from ordering the transfer of lawfully owned firearms to a third party as long as the defendant will neither use them nor direct their use.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"137 S. Ct. 1718","y":2017,"id":"2016/16-349","sc":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"1":"36, 40, 41"}},{"t":"case","label":"Kellogg Brown & Root Services, Inc. v. U.S. ex rel. Carter","cite":"135 S. Ct. 1970","y":2015,"id":"2014/12-1497","sc":1,"sum":"The Wartime Suspension of Limitations Act's statute of limitations tolling provision does not apply to claims of civil fraud brought by private parties. The False Claims Act's \"first-to-file bar\" keeps new claims out of court only while related claims are still alive, but not in perpetuity.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Kingdomware Technologies, Inc. v. United States","cite":"136 S. Ct. 1969","y":2016,"id":"2015/14-916","sc":1,"op":1,"sum":"The Court determined that the Court had jurisdiction to address the merits of the case even if the contracts had already been performed, and the Department of Veterans Affairs’ “set-aside” for veteran-owned businesses is mandatory.","sumSrc":"Oyez","by":{"1":"15"}},{"t":"case","label":"-v- Krys v. Pigott","cite":"749 F.3d 117","y":2014,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/749/117/","sum":"Holding that “actual knowledge of the procedures used or not used by the fiduciar[ies]” is often needed for imprudent-investment claims.","sumSrc":"brief:1","by":{"1":"17"}},{"t":"case","label":"L.I Head Start Child Development Services, Inc. v. Economic Opportunity Commission, Inc.","cite":"710 F.3d 57","y":2013,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/710/57/","by":{"1":"18"}},{"t":"case","label":"Martin v. Consultants & Administrators, Inc.","cite":"966 F.2d 1078","y":1992,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/966/1078/","by":{"1":"5"}},{"t":"case","label":"Merck & Co., Inc. v. Reynolds","cite":"559 U.S. 633","y":2010,"id":"2009/08-905","sc":1,"op":5,"sum":"The Court held that a statute of limitations begins to run once a plaintiff actually discovers -- or a reasonably diligent plaintiff would have discovered -- the facts constituting the violation in the present case, whichever comes first.","sumSrc":"Oyez","by":{"1":"17, 18, 20","2":"12, 13, 17, 18"}},{"t":"case","label":"New Prime v. Oliveira","cite":"139 S. Ct. 532","y":2019,"id":"2018/17-340","sc":1,"sum":"A court should determine whether the Federal Arbitration Act’s §1 exclusion for disputes involving the “contracts of employment” of certain transportation workers applies before ordering arbitration; here, truck driver Oliveira’s independent contractor operating agreement with New Prime falls within that exception.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"31"}},{"t":"case","label":"Pennwalt Corp. v. Nasios","cite":"550 A.2d 1155","y":1988,"court":"Md.","url":"https://www.courtlistener.com/c/A.2d/550/1155/","by":{"1":"30"}},{"t":"case","label":"Radiology Center, S.C. v. Stifel, Nicolaus & Co.","cite":"919 F.2d 1216","y":1990,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/919/1216/","op":1,"by":{"1":"18","2":"13"}},{"t":"case","label":"Ross v. Blake","cite":"136 S. Ct. 1850","y":2016,"id":"2015/15-339","sc":1,"sum":"The Court determined that the Prison Litigation Reform Act’s requirement to exhaust administrative remedies does not have a “special circumstances” exception.","sumSrc":"Oyez","by":{"1":"15","2":"16"}},{"t":"case","label":"Sandifer v. U.S. Steel Corp.","cite":"571 U.S. 220","y":2014,"id":"2013/12-417","sc":1,"sum":"The Court held that putting on safety garments constitutes \"changing clothes\" under the Fair Labor Standards Act.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"-vi- Scharff v. Raytheon Co. Short-Term Disability Plan","cite":"581 F.3d 899","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/581/899/","by":{"1":"33"}},{"t":"case","label":"Sebelius v. Cloer","cite":"569 U.S. 369","y":2013,"id":"2012/12-236","sc":1,"sum":"The Court found that a person who petitions under the National Childhood Vaccine Injury Act can recover attorney's fees regardless of if the petition was ultimately successful.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Tibble v. Edison International","cite":"135 S. Ct. 1823","y":2015,"id":"2014/13-550","sc":1,"sum":"The Court held that, according to trust law, the fiduciary duty includes a continuing duty to monitor investments, and that a breach of that duty within six years of the filing of a lawsuit under the Employee Retirement Income Security Act is sufficient to allow the case to proceed.","sumSrc":"Oyez","by":{"1":"5, 40"}},{"t":"case","label":"U.S. Commodity Futures Trading Commission v. Hunter Wise Commodities, LLC","cite":"749 F.3d 967","y":2014,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/749/967/","sum":"Holding that “actual knowledge of the procedures used or not used by the fiduciar[ies]” is often needed for imprudent-investment claims.","sumSrc":"brief:1","by":{"1":"33, 34"}},{"t":"case","label":"United States v. Myers","cite":"772 F.3d 213","y":2014,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/772/213/","by":{"1":"17"}},{"t":"case","label":"United States v. Spinney","cite":"65 F.3d 231","y":1995,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/65/231/","by":{"1":"17"}},{"t":"case","label":"Zirnhelt v. Michigan Consolidated Gas Co.","cite":"526 F.3d 282","y":2008,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/526/282/","by":{"1":"15"}},{"t":"usc","label":"12 U.S.C. § 1701q-1","url":"https://www.law.cornell.edu/uscode/text/12/1701q-1","by":{"1":"26"}},{"t":"usc","label":"12 U.S.C. § 1723i","url":"https://www.law.cornell.edu/uscode/text/12/1723i","by":{"1":"26"}},{"t":"usc","label":"12 U.S.C. § 1735f-15","url":"https://www.law.cornell.edu/uscode/text/12/1735f-15","by":{"1":"26"}},{"t":"usc","label":"15 U.S.C. § 1717a","url":"https://www.law.cornell.edu/uscode/text/15/1717a","by":{"1":"26"}},{"t":"usc","label":"17 U.S.C. § 1401","url":"https://www.law.cornell.edu/uscode/text/17/1401","subs":["(c)(6)(C)"],"by":{"1":"26"}},{"t":"usc","label":"21 U.S.C. § 335a","url":"https://www.law.cornell.edu/uscode/text/21/335a","subs":["(b)(2)(B)"],"by":{"1":"26"}},{"t":"usc","label":"29 U.S.C. § 1025","url":"https://www.law.cornell.edu/uscode/text/29/1025","by":{"1":"7"}},{"t":"usc","label":"29 U.S.C. § 1303","url":"https://www.law.cornell.edu/uscode/text/29/1303","subs":["(e)","(e)(6)(B)(i)","(e)(6)"],"stext":{"head":"§1303. Operation of corporation","paras":[[0,"(a) Investigatory authority; audit of statistically significant number of terminating plans"],[0,"The corporation may make such investigations as it deems necessary to enforce any provision of this subchapter or any rule or regulation thereunder, and may require or permit any person to file with it a statement in writing, under oath or otherwise as the corporation shall determine, as to all the facts and circumstances concerning the matter to be investigated. The corporation shall annually audit a statistically significant number of plans terminating under section 1341(b) of this title to determine whether participants and beneficiaries have received their benefit commitments and whether section 1350(a) of this title has been satisfied. Each audit shall include a statistically significant number of participants and beneficiaries."],[0,"(b) Discovery powers vested in board members or officers designated by the chairman"],[0,"For the purpose of any such investigation, or any other proceeding under this subchapter, the Director, any member of the board of directors of the corporation, or any officer designated by the Director or chairman, may administer oaths and affirmations, subpena witnesses, compel their attendance, take evidence, and require the production of any books, papers, correspondence, memoranda, or other records which the corporation deems relevant or material to the inquiry."],[0,"(c) Contempt"],[0,"In the case of contumacy by, or refusal to obey a subpena issued to, any person, the corporation may invoke the aid of any court of the United States within the jurisdiction of which such investigation or proceeding is carried on, or where such person resides or carries on business, in requiring the attendance and testimony of witnesses and the production of books, papers, correspondence, memoranda, and other records. The court may issue an order requiring such person to appear before the corporation, or member or officer designated by the corporation, and to produce records or to give testimony related to the matter under investigation or in question. Any failure to obey such order of the court may be punished by the court as a contempt thereof. All process in any such case may be served in the judicial district in which such person is an inhabitant or may be found."],[0,"(d) Cooperation with other governmental agencies"],[0,"In order to avoid unnecessary expense and duplication of functions among government agencies, the corporation may make such arrangements or agreements for cooperation or mutual assistance in the performance of its functions under this subchapter as is practicable and consistent with law. The corporation may utilize the facilities or services of any department, agency, or establishment of the United States or of any State or political subdivision of a State, including the services of any of its employees, with the lawful consent of such department, agency, or establishment. The head of each department, agency, or establishment of the United States shall cooperate with the corporation and, to the extent permitted by law, provide such information and facilities as it may request for its assistance in the performance of its functions under this subchapter. The Attorney General or his representative shall receive from the corporation for appropriate action such evidence developed in the performance of its functions under this subchapter as may be found to warrant consideration for criminal prosecution under the provisions of this or any other Federal law."],[0,"(e) Civil actions by corporation; jurisdiction; process; expeditious handling of case; costs; limitation on actions"],[0,"(1) Civil actions may be brought by the corporation for appropriate relief, legal or equitable or both, to enforce (A) the provisions of this subchapter, and (B) in the case of a plan which is covered under this subchapter (other than a multiemployer plan) and for which the conditions for imposition of a lien described in section 1083(k)(1)(A) and (B) or 1085a(g)(1)(A) and (B) of this title or section 430(k)(1)(A) and (B) or 433(g)(1)(A) and (B) of title 26 have been met, section 1082 of this title and section 412 of title 26."],[0,"(2) Except as otherwise provided in this subchapter, where such an action is brought in a district court of the United States, it may be brought in the district where the plan is administered, where the violation took place, or where a defendant resides or may be found, and process may be served in any other district where a defendant resides or may be found."],[0,"(3) The district courts of the United States shall have jurisdiction of actions brought by the corporation under this subchapter without regard to the amount in controversy in any such action."],[0,"(4) Repealed. Pub. L. 98–620, title IV, §402(33), Nov. 8, 1984, 98 Stat. 3360."],[0,"(5) In any action brought under this subchapter, whether to collect premiums, penalties, and interest under section 1307 of this title or for any other purpose, the court may award to the corporation all or a portion of the costs of litigation incurred by the corporation in connection with such action."],[0,"(6)(A) Except as provided in subparagraph (C), an action under this subsection may not be brought after the later of—"],[1,"(i) 6 years after the date on which the cause of action arose, or"],[1,"(ii) 3 years after the applicable date specified in subparagraph (B)."],[0,"(B)(i) Except as provided in clause (ii), the applicable date specified in this subparagraph is the earliest date on which the corporation acquired or should have acquired actual knowledge of the existence of such cause of action."],[0,"(ii) If the corporation brings the action as a trustee, the applicable date specified in this subparagraph is the date on which the corporation became a trustee with respect to the plan if such date is later than the date described in clause (i)."],[0,"(C) In the case of fraud or concealment, the period described in subparagraph (A)(ii) shall be extended to 6 years after the applicable date specified in subparagraph (B)."],[0,"(f) Civil actions against corporation; appropriate court; award of costs and expenses; limitation on actions; jurisdiction; removal of actions"],[0,"(1) Except with respect to withdrawal liability disputes under part 1 of subtitle E, any person who is a plan sponsor, fiduciary, employer, contributing sponsor, member of a contributing sponsor's controlled group, participant, or beneficiary, and is adversely affected by any action of the corporation with respect to a plan in which such person has an interest, or who is an employee organization representing such a participant or beneficiary so adversely affected for purposes of collective bargaining with respect to such plan, may bring an action against the corporation for appropriate equitable relief in the appropriate court."],[0,"(2) For purposes of this subsection, the term \"appropriate court\" means—"],[1,"(A) the United States district court before which proceedings under section 1341 or 1342 of this title are being conducted,"],[1,"(B) if no such proceedings are being conducted, the United States district court for the judicial district in which the plan has its principal office, or"],[1,"(C) the United States District Court for the District of Columbia."],[0,"(3) In any action brought under this subsection, the court may award all or a portion of the costs and expenses incurred in connection with such action to any party who prevails or substantially prevails in such action."],[0,"(4) This subsection shall be the exclusive means for bringing actions against the corporation under this subchapter, including actions against the corporation in its capacity as a trustee under section 1342 or 1349 1 of this title."],[0,"(5)(A) Except as provided in subparagraph (C), an action under this subsection may not be brought after the later of—"],[1,"(i) 6 years after the date on which the cause of action arose, or"],[1,"(ii) 3 years after the applicable date specified in subparagraph (B)."],[0,"(B)(i) Except as provided in clause (ii), the applicable date specified in this subparagraph is the earliest date on which the plaintiff acquired or should have acquired actual knowledge of the existence of such cause of action."],[0,"(ii) In the case of a plaintiff who is a fiduciary bringing the action in the exercise of fiduciary duties, the applicable date specified in this subparagraph is the date on which the plaintiff became a fiduciary with respect to the plan if such date is later than the date specified in clause (i)."],[0,"(C) In the case of fraud or concealment, the period described in subparagraph (A)(ii) shall be extended to 6 years after the applicable date specified in subparagraph (B)."],[0,"(6) The district courts of the United States have jurisdiction of actions brought under this subsection without regard to the amount in controversy."],[0,"(7) In any suit, action, or proceeding in which the corporation is a party, or intervenes under section 1451 of this title, in any State court, the corporation may, without bond or security, remove such suit, action, or proceeding from the State court to the United States district court for the district or division in which such suit, action, or proceeding is pending by following any procedure for removal now or hereafter in effect."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1303?type=usc&year=mostrecent&link-type=html"},"head":"§1303. Operation of corporation","tname":"Labor","by":{"1":"passim","2":"8, 19, 19","3":"14"}},{"t":"usc","label":"29 U.S.C. § 1370","url":"https://www.law.cornell.edu/uscode/text/29/1370","subs":["(f)(2)(A)"],"stext":{"head":"§1370. Enforcement authority relating to terminations of single-employer plans","paras":[[0,"(a) In general"],[0,"Any person who is with respect to a single-employer plan a fiduciary, contributing sponsor, member of a contributing sponsor's controlled group, participant, or beneficiary, and is adversely affected by an act or practice of any party (other than the corporation) in violation of any provision of section 1341, 1342, 1362, 1363, 1364, or 1369 of this title, or who is an employee organization representing such a participant or beneficiary so adversely affected for purposes of collective bargaining with respect to such plan, may bring an action—"],[1,"(1) to enjoin such act or practice, or"],[1,"(2) to obtain other appropriate equitable relief (A) to redress such violation or (B) to enforce such provision."],[0,"(b) Status of plan as party to action and with respect to legal process"],[0,"A single-employer plan may be sued under this section as an entity. Service of summons, subpoena, or other legal process of a court upon a trustee or an administrator of a single-employer plan in such trustee's or administrator's capacity as such shall constitute service upon the plan. If a plan has not designated in the summary plan description of the plan an individual as agent for the service of legal process, service upon any contributing sponsor of the plan shall constitute such service. Any money judgment under this section against a single-employer plan shall be enforceable only against the plan as an entity and shall not be enforceable against any other person unless liability against such person is established in such person's individual capacity."],[0,"(c) Jurisdiction and venue"],[0,"The district courts of the United States shall have exclusive jurisdiction of civil actions under this section. Such actions may be brought in the district where the plan is administered, where the violation took place, or where a defendant resides or may be found, and process may be served in any other district where a defendant resides or may be found. The district courts of the United States shall have jurisdiction, without regard to the amount in controversy or the citizenship of the parties, to grant the relief provided for in subsection (a) in any action."],[0,"(d) Right of corporation to intervene"],[0,"A copy of the complaint or notice of appeal in any action under this section shall be served upon the corporation by certified mail. The corporation shall have the right in its discretion to intervene in any action."],[0,"(e) Awards of costs and expenses"],[0,"(1) General rule"],[1,"In any action brought under this section, the court in its discretion may award all or a portion of the costs and expenses incurred in connection with such action, including reasonable attorney's fees, to any party who prevails or substantially prevails in such action."],[0,"(2) Exemption for plans"],[1,"Notwithstanding the preceding provisions of this subsection, no plan shall be required in any action to pay any costs and expenses (including attorney's fees)."],[0,"(f) Limitation on actions"],[0,"(1) In general"],[1,"Except as provided in paragraph (3), an action under this section may not be brought after the later of—"],[2,"(A) 6 years after the date on which the cause of action arose, or"],[2,"(B) 3 years after the applicable date specified in paragraph (2)."],[0,"(2) Applicable date"],[0,"(A) General rule"],[2,"Except as provided in subparagraph (B), the applicable date specified in this paragraph is the earliest date on which the plaintiff acquired or should have acquired actual knowledge of the existence of such cause of action."],[0,"(B) Special rule for plaintiffs who are fiduciaries"],[2,"In the case of a plaintiff who is a fiduciary bringing the action in the exercise of fiduciary duties, the applicable date specified in this paragraph is the date on which the plaintiff became a fiduciary with respect to the plan if such date is later than the date described in subparagraph (A)."],[0,"(3) Cases of fraud or concealment"],[1,"In the case of fraud or concealment, the period described in paragraph (1)(B) shall be extended to 6 years after the applicable date specified in paragraph (2)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1370?type=usc&year=mostrecent&link-type=html"},"head":"§1370. Enforcement authority relating to terminations of single-employer plans","tname":"Labor","by":{"1":"passim","2":"19","3":"14"}},{"t":"usc","label":"29 U.S.C. § 1451","url":"https://www.law.cornell.edu/uscode/text/29/1451","subs":["(f)"],"stext":{"head":"§1451. Civil actions","paras":[[0,"(a) Persons entitled to maintain actions"],[0,"(1) A plan fiduciary, employer, plan participant, or beneficiary, who is adversely affected by the act or omission of any party under this subtitle with respect to a multiemployer plan, or an employee organization which represents such a plan participant or beneficiary for purposes of collective bargaining, may bring an action for appropriate legal or equitable relief, or both."],[0,"(2) Notwithstanding paragraph (1), this section does not authorize an action against the Secretary of the Treasury, the Secretary of Labor, or the corporation."],[0,"(b) Failure of employer to make withdrawal liability payment within prescribed time"],[0,"In any action under this section to compel an employer to pay withdrawal liability, any failure of the employer to make any withdrawal liability payment within the time prescribed shall be treated in the same manner as a delinquent contribution (within the meaning of section 1145 of this title)."],[0,"(c) Jurisdiction of Federal and State courts"],[0,"The district courts of the United States shall have exclusive jurisdiction of an action under this section without regard to the amount in controversy, except that State courts of competent jurisdiction shall have concurrent jurisdiction over an action brought by a plan fiduciary to collect withdrawal liability."],[0,"(d) Venue and service of process"],[0,"An action under this section may be brought in the district where the plan is administered or where a defendant resides or does business, and process may be served in any district where a defendant resides, does business, or may be found."],[0,"(e) Costs and expenses"],[0,"In any action under this section, the court may award all or a portion of the costs and expenses incurred in connection with such action, including reasonable attorney's fees, to the prevailing party."],[0,"(f) Time limitations"],[0,"An action under this section may not be brought after the later of—"],[1,"(1) 6 years after the date on which the cause of action arose, or"],[1,"(2) 3 years after the earliest date on which the plaintiff acquired or should have acquired actual knowledge of the existence of such cause of action; except that in the case of fraud or concealment, such action may be brought not later than 6 years after the date of discovery of the existence of such cause of action."],[0,"(g) Service of complaint on corporation; intervention by corporation"],[0,"A copy of the complaint in any action under this section or section 1401 of this title shall be served upon the corporation by certified mail. The corporation may intervene in any such action."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1451?type=usc&year=mostrecent&link-type=html"},"head":"§1451. Civil actions","tname":"Labor","by":{"1":"passim","2":"19"}},{"t":"usc","label":"29 U.S.C. § 1658","url":"https://www.law.cornell.edu/uscode/text/29/1658","subs":["(b)(1)"],"by":{"1":"18"}},{"t":"usc","label":"31 U.S.C. § 3729","url":"https://www.law.cornell.edu/uscode/text/31/3729","subs":["(b)(1)","(b)(1)(A)"],"stext":{"head":"§3729. False claims","paras":[[0,"(a) Liability for Certain Acts.—"],[1,"(1) In general.—Subject to paragraph (2), any person who—"],[2,"(A) knowingly presents, or causes to be presented, a false or fraudulent claim for payment or approval;"],[2,"(B) knowingly makes, uses, or causes to be made or used, a false record or statement material to a false or fraudulent claim;"],[2,"(C) conspires to commit a violation of subparagraph (A), (B), (D), (E), (F), or (G);"],[2,"(D) has possession, custody, or control of property or money used, or to be used, by the Government and knowingly delivers, or causes to be delivered, less than all of that money or property;"],[2,"(E) is authorized to make or deliver a document certifying receipt of property used, or to be used, by the Government and, intending to defraud the Government, makes or delivers the receipt without completely knowing that the information on the receipt is true;"],[2,"(F) knowingly buys, or receives as a pledge of an obligation or debt, public property from an officer or employee of the Government, or a member of the Armed Forces, who lawfully may not sell or pledge property; or"],[2,"(G) knowingly makes, uses, or causes to be made or used, a false record or statement material to an obligation to pay or transmit money or property to the Government, or knowingly conceals or knowingly and improperly avoids or decreases an obligation to pay or transmit money or property to the Government,"],[1,"is liable to the United States Government for a civil penalty of not less than $5,000 and not more than $10,000, as adjusted by the Federal Civil Penalties Inflation Adjustment Act of 1990 (28 U.S.C. 2461 note; Public Law 104–410 1), plus 3 times the amount of damages which the Government sustains because of the act of that person."],[1,"(2) Reduced damages.—If the court finds that—"],[2,"(A) the person committing the violation of this subsection furnished officials of the United States responsible for investigating false claims violations with all information known to such person about the violation within 30 days after the date on which the defendant first obtained the information;"],[2,"(B) such person fully cooperated with any Government investigation of such violation; and"],[2,"(C) at the time such person furnished the United States with the information about the violation, no criminal prosecution, civil action, or administrative action had commenced under this title with respect to such violation, and the person did not have actual knowledge of the existence of an investigation into such violation,"],[1,"the court may assess not less than 2 times the amount of damages which the Government sustains because of the act of that person."],[1,"(3) Costs of civil actions.—A person violating this subsection shall also be liable to the United States Government for the costs of a civil action brought to recover any such penalty or damages."],[0,"(b) Definitions.—For purposes of this section—"],[1,"(1) the terms \"knowing\" and \"knowingly\"—"],[2,"(A) mean that a person, with respect to information—"],[3,"(i) has actual knowledge of the information;"],[3,"(ii) acts in deliberate ignorance of the truth or falsity of the information; or"],[3,"(iii) acts in reckless disregard of the truth or falsity of the information; and"],[2,"(B) require no proof of specific intent to defraud;"],[1,"(2) the term \"claim\"—"],[2,"(A) means any request or demand, whether under a contract or otherwise, for money or property and whether or not the United States has title to the money or property, that—"],[3,"(i) is presented to an officer, employee, or agent of the United States; or"],[3,"(ii) is made to a contractor, grantee, or other recipient, if the money or property is to be spent or used on the Government's behalf or to advance a Government program or interest, and if the United States Government—"],[4,"(I) provides or has provided any portion of the money or property requested or demanded; or"],[4,"(II) will reimburse such contractor, grantee, or other recipient for any portion of the money or property which is requested or demanded; and"],[2,"(B) does not include requests or demands for money or property that the Government has paid to an individual as compensation for Federal employment or as an income subsidy with no restrictions on that individual's use of the money or property;"],[1,"(3) the term \"obligation\" means an established duty, whether or not fixed, arising from an express or implied contractual, grantor-grantee, or licensor-licensee relationship, from a fee-based or similar relationship, from statute or regulation, or from the retention of any overpayment; and"],[1,"(4) the term \"material\" means having a natural tendency to influence, or be capable of influencing, the payment or receipt of money or property."],[0,"(c) Exemption From Disclosure.—Any information furnished pursuant to subsection (a)(2) shall be exempt from disclosure under section 552 of title 5."],[0,"(d) Exclusion.—This section does not apply to claims, records, or statements made under the Internal Revenue Code of 1986."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/31/3729?type=usc&year=mostrecent&link-type=html"},"head":"§3729. False claims","tname":"Money and Finance","by":{"1":"26","2":"21"}},{"t":"usc","label":"31 U.S.C. § 3801","url":"https://www.law.cornell.edu/uscode/text/31/3801","subs":["(a)(5)"],"by":{"1":"26"}},{"t":"usc","label":"42 U.S.C. § 1437z-1","url":"https://www.law.cornell.edu/uscode/text/42/1437z-1","by":{"1":"26"}},{"t":"usc","label":"42 U.S.C. § 3537a","url":"https://www.law.cornell.edu/uscode/text/42/3537a","by":{"1":"26"}},{"t":"usc","label":"42 U.S.C. § 3545","url":"https://www.law.cornell.edu/uscode/text/42/3545","subs":["(m)"],"by":{"1":"26"}},{"t":"case","label":"Azar v. Allina Health Servs.","cite":"139 S. Ct. 1804","y":2019,"id":"2018/17-1484","sc":1,"op":1,"sum":"Because the Department of Health and Human Services neglected its statutory notice-and-comment obligations when it revealed a new policy that dramatically—and retroactively—reduced Medicare payments to hospitals serving low-income patients, its policy must be vacated.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"29"}},{"t":"case","label":"Brock v. TIC Int’l Corp.","cite":"785 F.2d 168","y":1986,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/785/168/","by":{"2":"28","3":"14"}},{"t":"case","label":"Bullock v. BankChampaign, N.A.","cite":"569 U.S. 267","y":2013,"id":"2012/11-1518","sc":1,"sum":"The Court held that debts arising out of fraud or defalcation in a fiduciary capacity are not dischargeable in bankruptcy proceedings.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"CTS Corp. v. Waldburger","cite":"573 U.S. 1","y":2014,"id":"2013/13-339","sc":1,"sum":"The Court found that the Comprehensive Environmental Response, Compensation, and Liability Act pre-empts statutes of limitations, but cannot be used to pre-empt statutes of repose.","sumSrc":"Oyez","by":{"2":"30","3":"16"}},{"t":"case","label":"City of Corsicana v. Stewart","cite":"249 S.W.3d 412","y":2008,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.3d/249/412/","by":{"2":"14"}},{"t":"case","label":"Gebser v. Lago Vista Indep. Sch. Dist.","cite":"524 U.S. 274","y":1998,"id":"1997/96-1866","sc":1,"sum":"In a 5-to-4 decision the Court held that two minimal criteria must be met in order for an aggrieved party to recover sexual harassment damages under the Amendments. First, the party must show that a school district official, with the ability to institute corrective measures, knew of the forbidden conduct.","sumSrc":"Oyez","by":{"2":"12"}},{"t":"case","label":"Gross v. FBL Fin. Servs., Inc.","cite":"557 U.S. 167","y":2009,"id":"2008/08-441","sc":1,"sum":"The Court held that a plaintiff must show that age was the \"but-for\" cause for the defendant's action in an Age Discrimination in Employment Act claim.","sumSrc":"Oyez","by":{"2":"11"}},{"t":"case","label":"Holmberg v. Armbrecht","cite":"327 U.S. 392","y":1946,"id":"scdb/1945-049","sc":1,"sum":"1. Decision of a suit in a federal court to enforce a federally created equitable right is not controlled by the statute of limitations of the State of the forum. Guaranty Trust Co. v. York, 326 U. S. 99, distinguished. Accordingly, a class suit by creditors of a joint stock land bank to enforce the liability imposed upon shareholders of the bank by § 16 of the Federal Farm Loan Act is not barred by the state …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"18"}},{"t":"case","label":"J. Geils Band Emp. Benefit Plan v. Smith Barney Shearson, Inc.","cite":"76 F.3d 1245","y":1996,"url":"https://www.courtlistener.com/c/F.3d/76/1245/","by":{"2":"18"}},{"t":"case","label":"Mitchell v. Commissioner","cite":"292 F.3d 800","y":2002,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/292/800/","sum":"Observing outside the ERISA context that mere “reason to know” would not satisfy a statutory requirement of “actual knowledge”.","sumSrc":"brief:2","by":{"2":"13"}},{"t":"case","label":"Pressley v. Tupperware Long Term Disability Plan","cite":"553 F.3d 334","y":2009,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/553/334/","by":{"2":"24"}},{"t":"case","label":"Reich v. Lancaster","cite":"55 F.3d 1034","y":1995,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/55/1034/","op":1,"by":{"2":"13"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"17, 20"}},{"t":"case","label":"Scott v. Harris","cite":"550 U.S. 372","y":2007,"id":"2006/05-1631","sc":1,"op":2,"sum":"The Court ruled 8-1 that Scott's actions were reasonable under the Fourth Amendment. The opinion by Justice Antonin Scalia relied heavily on a videotape of the car chase, which it said contradicted the plaintiff's claim that he was driving responsibly even while being pursued by the police.","sumSrc":"Oyez","by":{"2":"31"}},{"t":"case","label":"Secretary v. Preston","cite":"873 F.3d 877","y":2017,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/873/877/","by":{"2":"29"}},{"t":"case","label":"Stone v. INS","cite":"514 U.S. 386","y":1995,"id":"1994/93-1199","sc":1,"sum":"A timely motion for reconsideration of a BIA decision does not toll the running of § 106(a)(1)'s 90-day period.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"16"}},{"t":"case","label":"Stone v. Travelers Corp.","cite":"58 F.3d 434","y":1995,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/58/434/","by":{"2":"24"}},{"t":"case","label":"Travis v. Dreis & Krump Mfg. Co.","cite":"551 N.W.2d 132","y":1996,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W.2d/551/132/","by":{"2":"14"}},{"t":"case","label":"Universal Health Servs. v. United States ex rel. Escobar","cite":"136 S. Ct. 1989","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./136/1989/","sc":1,"by":{"2":"12, 21"}},{"t":"case","label":"West Va. Univ. Hosps., Inc. v. Casey","cite":"499 U.S. 83","y":1991,"id":"1990/89-994","sc":1,"sum":"Fees for services rendered by experts in civil rights litigation may not be shifted to the losing party as part of \"a reasonable attorney's fee\" under § 1988.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"17"}},{"t":"usc","label":"20 U.S.C. § 1681","url":"https://www.law.cornell.edu/uscode/text/20/1681","by":{"2":"13"}},{"t":"usc","label":"29 U.S.C. § 1002","url":"https://www.law.cornell.edu/uscode/text/29/1002","subs":["(13)","(21)(A)"],"by":{"2":"1, 2"}},{"t":"usc","label":"29 U.S.C. § 1023","url":"https://www.law.cornell.edu/uscode/text/29/1023","subs":["(b)"],"by":{"2":"27"}},{"t":"usc","label":"29 U.S.C. § 1085","url":"https://www.law.cornell.edu/uscode/text/29/1085","subs":["(e)(9)(I)(iv)"],"stext":{"head":"§1085. Additional funding rules for multiemployer plans in endangered status or critical status","paras":[[0,"(a) General rule"],[0,"For purposes of this part, in the case of a multiemployer plan in effect on July 16, 2006—"],[1,"(1) if the plan is in endangered status—"],[2,"(A) the plan sponsor shall adopt and implement a funding improvement plan in accordance with the requirements of subsection (c), and"],[2,"(B) the requirements of subsection (d) shall apply during the funding plan adoption period and the funding improvement period,"],[1,"(2) if the plan is in critical status—"],[2,"(A) the plan sponsor shall adopt and implement a rehabilitation plan in accordance with the requirements of subsection (e), and"],[2,"(B) the requirements of subsection (f) shall apply during the rehabilitation plan adoption period and the rehabilitation period, and"],[1,"(3) if the plan is in critical and declining status—"],[2,"(A) the requirements of paragraph (2) shall apply to the plan; and"],[2,"(B) the plan sponsor may, by plan amendment, suspend benefits in accordance with the requirements of subsection (e)(9)."],[0,"(b) Determination of endangered and critical status"],[0,"For purposes of this section—"],[0,"(1) Endangered status"],[1,"A multiemployer plan is in endangered status for a plan year if, as determined by the plan actuary under paragraph (3), the plan is not in critical status for the plan year and is not described in paragraph (5), and, as of the beginning of the plan year, either—"],[2,"(A) the plan's funded percentage for such plan year is less than 80 percent, or"],[2,"(B) the plan has an accumulated funding deficiency for such plan year, or is projected to have such an accumulated funding deficiency for any of the 6 succeeding plan years, taking into account any extension of amortization periods under section 1084(d) of this title."],[1,"For purposes of this section, a plan shall be treated as in seriously endangered status for a plan year if the plan is described in both subparagraphs (A) and (B)."],[0,"(2) Critical status"],[1,"A multiemployer plan is in critical status for a plan year if, as determined by the plan actuary under paragraph (3), the plan is described in 1 or more of the following subparagraphs as of the beginning of the plan year:"],[2,"(A) A plan is described in this subparagraph if—"],[3,"(i) the funded percentage of the plan is less than 65 percent, and"],[3,"(ii) the sum of—"],[4,"(I) the fair market value of plan assets, plus"],[4,"(II) the present value of the reasonably anticipated employer contributions for the current plan year and each of the 6 succeeding plan years, assuming that the terms of all collective bargaining agreements pursuant to which the plan is maintained for the current plan year continue in effect for succeeding plan years,"],[0,"is less than the present value of all nonforfeitable benefits projected to be payable under the plan during the current plan year and each of the 6 succeeding plan years (plus administrative expenses for such plan years)."],[2,"(B) A plan is described in this subparagraph if—"],[3,"(i) the plan has an accumulated funding deficiency for the current plan year, not taking into account any extension of amortization periods under section 1084(d) of this title, or"],[3,"(ii) the plan is projected to have an accumulated funding deficiency for any of the 3 succeeding plan years (4 succeeding plan years if the funded percentage of the plan is 65 percent or less), not taking into account any extension of amortization periods under section 1084(d) of this title."],[2,"(C) A plan is described in this subparagraph if—"],[3,"(i)(I) the plan's normal cost for the current plan year, plus interest (determined at the rate used for determining costs under the plan) for the current plan year on the amount of unfunded benefit liabilities under the plan as of the last date of the preceding plan year, exceeds"],[3,"(II) the present value of the reasonably anticipated employer and employee contributions for the current plan year,"],[3,"(ii) the present value, as of the beginning of the current plan year, of nonforfeitable benefits of inactive participants is greater than the present value of nonforfeitable benefits of active participants, and"],[3,"(iii) the plan has an accumulated funding deficiency for the current plan year, or is projected to have such a deficiency for any of the 4 succeeding plan years, not taking into account any extension of amortization periods under section 1084(d) of this title."],[2,"(D) A plan is described in this subparagraph if the sum of—"],[3,"(i) the fair market value of plan assets, plus"],[3,"(ii) the present value of the reasonably anticipated employer contributions for the current plan year and each of the 4 succeeding plan years, assuming that the terms of all collective bargaining agreements pursuant to which the plan is maintained for the current plan year continue in effect for succeeding plan years,"],[2,"is less than the present value of all benefits projected to be payable under the plan during the current plan year and each of the 4 succeeding plan years (plus administrative expenses for such plan years)."],[0,"(3) Annual certification by plan actuary"],[0,"(A) In general"],[2,"Not later than the 90th day of each plan year of a multiemployer plan, the plan actuary shall certify to the Secretary of the Treasury and to the plan sponsor—"],[3,"(i) whether or not the plan is in endangered status for such plan year, or would be in endangered status for such plan year but for paragraph (5),,1 whether or not the plan is or will be in critical status for such plan year or for any of the succeeding 5 plan years, and whether or not the plan is or will be in critical and declining status for such plan year, and"],[3,"(ii) in the case of a plan which is in a funding improvement or rehabilitation period, whether or not the plan is making the scheduled progress in meeting the requirements of its funding improvement or rehabilitation plan."],[0,"(B) Actuarial projections of assets and liabilities"],[0,"(i) In general"],[3,"Except as provided in clause (iv), in making the determinations and projections under this subsection, the plan actuary shall make projections required for the current and succeeding plan years of the current value of the assets of the plan and the present value of all liabilities to participants and beneficiaries under the plan for the current plan year as of the beginning of such year. The actuary's projections shall be based on reasonable actuarial estimates, assumptions, and methods that, except as provided in clause (iii), offer the actuary's best estimate of anticipated experience under the plan. The projected present value of liabilities as of the beginning of such year shall be determined based on the most recent of either—"],[4,"(I) the actuarial statement required under section 1023(d) of this title with respect to the most recently filed annual report, or"],[4,"(II) the actuarial valuation for the preceding plan year."],[0,"(ii) Determinations of future contributions"],[3,"Any actuarial projection of plan assets shall assume—"],[4,"(I) reasonably anticipated employer contributions for the current and succeeding plan years, assuming that the terms of the one or more collective bargaining agreements pursuant to which the plan is maintained for the current plan year continue in effect for succeeding plan years, or"],[4,"(II) that employer contributions for the most recent plan year will continue indefinitely, but only if the plan actuary determines there have been no significant demographic changes that would make such assumption unreasonable."],[0,"(iii) Projected industry activity"],[3,"Any projection of activity in the industry or industries covered by the plan, including future covered employment and contribution levels, shall be based on information provided by the plan sponsor, which shall act reasonably and in good faith."],[0,"(iv) 2 Projections relating to critical status in succeeding plan years"],[3,"Clauses (i) and (ii) (other than the 2nd sentence of clause (i)) may be disregarded by a plan actuary in the case of any certification of whether a plan will be in critical status in a succeeding plan year, except that a plan sponsor may not elect to be in critical status for a plan year under paragraph (4) in any case in which the certification upon which such election would be based is made without regard to such clauses."],[0,"(iv) 2 Projections of critical and declining status"],[3,"In determining whether a plan is in critical and declining status as described in subsection (e)(9), clauses (i), (ii), and (iii) shall apply, except that—"],[4,"(I) if reasonable, the plan actuary shall assume that each contributing employer in compliance continues to comply through the end of the rehabilitation period or such later time as provided in subsection (e)(3)(A)(ii) with the terms of the rehabilitation plan that correspond to the schedule adopted or imposed under subsection (e), and"],[4,"(II) the plan actuary shall take into account any suspensions of benefits described in subsection (e)(9) adopted in a prior plan year that are still in effect."],[0,"(C) Penalty for failure to secure timely actuarial certification"],[2,"Any failure of the plan's actuary to certify the plan's status under this subsection by the date specified in subparagraph (A) shall be treated for purposes of section 1132(c)(2) of this title as a failure or refusal by the plan administrator to file the annual report required to be filed with the Secretary under section 1021(b)(1) of this title."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1085?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1085. Additional funding rules for multiemployer plans in endangered status or critical status","tname":"Labor","by":{"2":"19"}},{"t":"usc","label":"29 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/29/1101","by":{"2":"24"}},{"t":"usc","label":"29 U.S.C. § 1102","url":"https://www.law.cornell.edu/uscode/text/29/1102","subs":["(a)(1)"],"by":{"2":"2"}},{"t":"usc","label":"29 U.S.C. § 1105","url":"https://www.law.cornell.edu/uscode/text/29/1105","subs":["(a)(3)"],"by":{"2":"29"}},{"t":"usc","label":"29 U.S.C. § 1106","url":"https://www.law.cornell.edu/uscode/text/29/1106","subs":["(a)","(b)"],"by":{"2":"6, 2, 2"}},{"t":"usc","label":"29 U.S.C. § 1109","url":"https://www.law.cornell.edu/uscode/text/29/1109","subs":["(a)"],"by":{"2":"29"}},{"t":"usc","label":"29 U.S.C. § 1136","url":"https://www.law.cornell.edu/uscode/text/29/1136","subs":["(b)"],"by":{"2":"28, 1"}},{"t":"usc","label":"29 U.S.C. § 1142","url":"https://www.law.cornell.edu/uscode/text/29/1142","by":{"2":"26"}},{"t":"law","label":"Pub. L. No. 96-364","url":"https://www.govinfo.gov/link/statute/94/1263","by":{"2":"19","3":"14"}},{"t":"law","label":"Pub. L. No. 113-235","url":"https://www.govinfo.gov/link/plaw/113/public/235","by":{"2":"19"}},{"t":"law","label":"Pub. L. No. 99-272","url":"https://www.govinfo.gov/link/statute/100/237","by":{"2":"19","3":"14"}},{"t":"usc","label":"15 U.S.C. § 45","url":"https://www.law.cornell.edu/uscode/text/15/45","subs":["(m)(1)(A)"],"by":{"2":"20"}},{"t":"usc","label":"15 U.S.C. § 77m","url":"https://www.law.cornell.edu/uscode/text/15/77m","by":{"2":"13"}},{"t":"usc","label":"15 U.S.C. § 1264","url":"https://www.law.cornell.edu/uscode/text/15/1264","subs":["(c)(5)"],"by":{"2":"20"}},{"t":"usc","label":"15 U.S.C. § 3414","url":"https://www.law.cornell.edu/uscode/text/15/3414","subs":["(b)(6)(B)"],"by":{"2":"20"}},{"t":"usc","label":"15 U.S.C. § 7704","url":"https://www.law.cornell.edu/uscode/text/15/7704","subs":["(a)(2)"],"by":{"2":"20"}},{"t":"usc","label":"21 U.S.C. § 387t","url":"https://www.law.cornell.edu/uscode/text/21/387t","subs":["(d)(2)"],"by":{"2":"20"}},{"t":"usc","label":"28 U.S.C. § 1658","url":"https://www.law.cornell.edu/uscode/text/28/1658","subs":["(b)(1)"],"by":{"2":"18"}},{"t":"usc","label":"42 U.S.C. § 6303","url":"https://www.law.cornell.edu/uscode/text/42/6303","subs":["(b)"],"by":{"2":"20"}},{"t":"rule","label":"Fed. R. Civ. P. 56","url":"https://www.law.cornell.edu/rules/frcp/rule_56","subs":["(c)"],"by":{"2":"31"}},{"t":"case","label":"FEDERAL CASES Aetna Health Inc. v. Davila","cite":"542 U.S. 200","y":2004,"id":"2003/02-1845","sc":1,"sum":"The Court held that Congress intended ERISA to provide a uniform system for regulating retirement schemes and benefits. If a state law conflicts with ERISA, therefore, ERISA must be used in its place.","sumSrc":"Oyez","by":{"3":"18"}},{"t":"case","label":"Conmar Corp. v. Mitsui & Co.","cite":"858 F.2d 499","y":1988,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/858/499/","by":{"3":"11"}},{"t":"case","label":"Di Joseph v. Standard Ins. Co.","cite":"776 F. App’x 343","y":2019,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/776/343/","by":{"3":"21"}},{"t":"case","label":"Egelhoff v. Egelhoff","cite":"532 U.S. 141","y":2001,"id":"2000/99-1529","sc":1,"sum":"The Court held that that the Washington statute has a \"connection with\" ERISA plans and is therefore pre-empted. \"Differing state regulations affecting an ERISA plan's 'system for processing claims and paying benefits' impose 'precisely the burden that ERISA pre-emption was intended to avoid,'\" wrote Justice Thomas.","sumSrc":"Oyez","by":{"3":"23"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"ar":2,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"3":"4"}},{"t":"case","label":"Gundy v. United States","cite":"139 S. Ct. 2116","y":2019,"id":"2018/17-6086","sc":1,"sum":"The Second Circuit’s judgment that 34 U. S. C. §20913(d)—which requires the Attorney General to apply the Sex Offender Registration and Notification Act’s registration requirements as soon as feasible to offenders convicted before the statute’s enactment—is not an unconstitutional delegation of legislative authority is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"5"}},{"t":"case","label":"Hard Rock Cafe Licensing Corp. v. Concession Servs., Inc.","cite":"955 F.2d 1143","y":1992,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/955/1143/","by":{"3":"9"}},{"t":"case","label":"John R. Sand & Gravel Co. v. United States","cite":"552 U.S. 130","y":2008,"id":"2007/06-1164","sc":1,"sum":"In a seven-member majority opinion written by Justice Stephen G. Breyer, the Court upheld the Federal Circuit ruling that the statute of limitations was \"jurisdictional,\" or a predicate for court authority. Breyer referred to roughly five decades of the Court's case law to determine that the doctrine of stare decisis required it to follow the time limit and dismiss John R. Sand's claim.","sumSrc":"Oyez","by":{"3":"16"}},{"t":"case","label":"King v. Blue Cross & Blue Shield of Illinois","cite":"871 F.3d 730","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/871/730/","ar":1,"by":{"3":"22"}},{"t":"case","label":"Rimini St., Inc. v. Oracle USA, Inc.","cite":"139 S. Ct. 873","y":2019,"id":"2018/17-1625","sc":1,"sum":"A federal district court’s discretion to award “full costs” to a party in copyright litigation pursuant to 17 U. S. C. §505 is limited to the six categories specified in the general costs statute codified at 28 U. S. C. §§1821 and 1920.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"7, 8"}},{"t":"case","label":"RRW Legacy Mgmt. Grp., Inc. v. Walker","cite":"751 F. App’x 993","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/751/993/","by":{"3":"9"}},{"t":"case","label":"Scalia v. WPN Corp.","cite":"2019 WL 4748052","y":2019,"court":"W.D. Pa. Sept. 30","by":{"3":"22"}},{"t":"case","label":"Shacket v. Philko Aviation, Inc.","cite":"841 F.2d 166","y":1988,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/841/166/","sum":"Describing “the form of actual knowledge that consists of closing your eyes because you’re afraid of what you would see if you opened them”.","sumSrc":"brief:3","by":{"3":"9"}},{"t":"case","label":"Shaw v. Delta Air Lines, Inc.","cite":"463 U.S. 85","y":1983,"id":"1982/81-1578","sc":1,"sum":"New York's Human Rights Law forbids discrimination in employee benefit plans on the basis of pregnancy, and its Disability Benefits Law requires employers to pay sick-leave benefits to employees unable to work because of pregnancy. Section 514(a) of the federal Employee Retirement Income Security Act of 1974 (ERISA) provides, with enumerated exceptions, that ERISA shall supersede \"any and all state laws insofar as …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"23"}},{"t":"case","label":"TC Heartland LLC v. Kraft Foods Grp. Brands LLC","cite":"137 S. Ct. 1514","y":2017,"id":"2016/16-341","sc":1,"sum":"The Court held that the subsection of the general venue statute that allows a corporation to reside in many jurisdictions for the purpose of establishing jurisdiction does not apply to the patent venue statute.","sumSrc":"Oyez","by":{"3":"8"}},{"t":"case","label":"United States v. Brooks","cite":"681 F.3d 678","y":2012,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/681/678/","by":{"3":"13"}},{"t":"case","label":"United States v. Farrell","cite":"921 F.3d 116","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/921/116/","by":{"3":"9"}},{"t":"case","label":"United States v. One 1973 Rolls Royce, V.I.N. SRH-16266","cite":"43 F.3d 794","y":1994,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/43/794/","by":{"3":"9"}},{"t":"case","label":"United States v. Ron Pair Enters., Inc.","cite":"489 U.S. 235","y":1989,"id":"1988/87-1043","sc":1,"sum":"Section 506(b) entitles a creditor to receive postpetition interest on a nonconsensual oversecured claim allowed in a bankruptcy proceeding.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"17"}},{"t":"case","label":"STATE CASES ABN AMRO Mortg. Grp., Inc. v. Roush","cite":"2005 WL 858182","y":2005,"court":"Ohio Ct. App.","by":{"3":"11"}},{"t":"case","label":"Black v. Pub. Serv. Elec. & Gas Co.","cite":"237 A.2d 495","y":1968,"court":"N.J. Super. Ct. App. Div.","url":"https://www.courtlistener.com/c/A.2d/237/495/","op":3,"by":{"3":"10"}},{"t":"case","label":"v Breckenridge v. Farber","cite":"640 So. 2d 208","y":1994,"court":"Fla. Dist. Ct. App.","url":"https://www.courtlistener.com/c/So.%202d/640/208/","by":{"3":"9, 10"}},{"t":"case","label":"Slachter v. Swanson","cite":"826 So. 2d 1012","y":2001,"court":"Fla. Dist. Ct. App.","url":"https://www.courtlistener.com/c/So.%202d/826/1012/","by":{"3":"10"}},{"t":"usc","label":"35 U.S.C. § 271","url":"https://www.law.cornell.edu/uscode/text/35/271","subs":["(b)"],"by":{"3":"8, 9"}}]};